// In der öffentlichen Demo kommen alle Daten aus mitgelieferten Dateien: was der Server
// je Anfrage rechnet (Artikel je Zeitraum, Suche über alle Keywords), gibt es dort nicht.
const DEMO = document.documentElement.hasAttribute("data-demo");

/* ---------- Leinwand und Geometrie ---------- */

const canvas = document.getElementById("c");
// alpha:false — der Hintergrund wird ohnehin jeden Frame gefüllt, das spart das Compositing.
const ctx = canvas.getContext("2d", { alpha: false });
// dpr auf 2 gedeckelt: bei dpr 3 (iPhone) kostet jeder Frame 2,25-mal so viele Pixel,
// sichtbar ist der Unterschied bei weichen Kreisen und Glow praktisch nicht.
let dpr = Math.min(2, window.devicePixelRatio || 1);
let W = 0, H = 0;

const tip = document.getElementById("tip");
const panel = document.getElementById("panel");
const legende = document.getElementById("legende");
const zeitleiste = document.getElementById("zeitleiste");
const slider = document.getElementById("woche");
const wochenlabel = document.getElementById("wochenlabel");
const playBtn = document.getElementById("play");

const esc = s => String(s ?? "").replace(/[&<>"']/g, c =>
  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
// Artikel-URLs stammen von gecrawlten Fremdseiten — nur http(s) ins href lassen.
const sicherUrl = u => /^https?:\/\//i.test(u || "") ? esc(u) : "#";

/* ---------- Farben ---------- */

// Reihenfolge = config.RUBRIKEN; dieselben Töne wie RUBRIK_FARBEN in web/app.js.
const PALETTE = ["#7aa2f7","#9ece6a","#e0af68","#3fb27f","#f7768e","#bb9af7","#73daca",
                 "#ff9e64","#7dcfff","#c0caf5","#ff757f","#4fd6be","#fca7ea",
                 "#a9b665","#d3869b","#89b4fa","#f2cdcd"];
/* Hell/Dunkel: die Canvas-Seite des Themas. Die Skalen brauchen je Schema eigene
   Endpunkte — auf Weiß ist "hell = aktiv" unsichtbar, also kehrt der Momentum-Verlauf
   dort um (blass = ruhig, dunkles Gold = aktiv). Kanten und Glow zeichnen im Dunkeln
   additiv ("lighter"); auf hellem Grund hebt Addition nichts mehr, dort gilt normales
   Zeichnen bzw. "multiply" für den Glow. */
const mediaHell = window.matchMedia("(prefers-color-scheme: light)");
const tabelle = skala => Array.from({ length: 256 }, (_, i) => skala(i / 255) + "");
let HELL, T, likeSkala, momSkala, fremdSkala, LIKE_LUT, MOM_LUT, FREMD_LUT;
let KEIN_THEMA, THEMA_GRAU, OHNE_WERT, NEUTRAL;
function setzeTheme() {
  HELL = mediaHell.matches;
  T = HELL ? {
    bg: "#fafafa", kante: "#7c86a8", kantenModus: "source-over", kantenFaktor: 0.55,
    kanteRueck: "#c3c9d8", knotenRueck: "#b6bccb", fokusRing: "#14171e",
    labelText: "#14171e", labelDim: "#4d5464", labelHalo: "rgba(250,250,250,.8)",
    hinweis: "#6b7280", glowModus: "multiply", hellwert: mag => 0.66 - 0.26 * mag,
  } : {
    bg: "#0b0e16", kante: "#67759f", kantenModus: "lighter", kantenFaktor: 1,
    kanteRueck: "#6f7ba6", knotenRueck: "#7d88b0", fokusRing: "#e6e9f2",
    labelText: "#e6e9f2", labelDim: "#aeb6cf", labelHalo: "rgba(11,14,22,.8)",
    hinweis: "#59617d", glowModus: "lighter", hellwert: mag => 0.85 - 0.23 * mag,
  };
  // Keywords ohne Thema/Wert bleiben grau — je Schema ein eigenes.
  KEIN_THEMA = HELL ? "#aab0c0" : "#4a5270";
  THEMA_GRAU = HELL ? "#e2e5ec" : "#232a42";
  OHNE_WERT = HELL ? "#c6ccd9" : "#2c3350";
  NEUTRAL = HELL ? "#9aa1b3" : "#7e88a8";   // ohne Einfärbung: deutlich heller als „kein Wert"
  likeSkala = d3.scaleLinear().domain([0, .5, 1])
    .range(HELL ? ["#e0566f", "#a7adc4", "#569c33"] : ["#f7768e", "#565f89", "#9ece6a"]).clamp(true);
  momSkala = d3.scaleLinear().domain([0, .45, 1])
    .range(HELL ? ["#e8ebf2", "#e0af68", "#9c5800"] : ["#1c2338", "#e0af68", "#fff3d8"]).clamp(true);
  // Fremdheit: die unteren zwei Drittel bleiben bewusst ein einheitliches Grau — sonst
  // erschiene die halbe Karte als leicht auffällig und die echten Ausreißer gingen unter.
  fremdSkala = d3.scaleLinear().domain([0, .62, .85, 1])
    .range(HELL ? ["#b6bccb", "#b6bccb", "#d64a72", "#e8174c"]
                : ["#39405c", "#39405c", "#c2607a", "#ff5d7a"]).clamp(true);
  // Farbskalen als 256-Stufen-Tabelle: beim Zeichnen bleibt ein Array-Zugriff statt
  // einer d3-Skalenauswertung je Knoten und Frame.
  LIKE_LUT = tabelle(likeSkala); MOM_LUT = tabelle(momSkala); FREMD_LUT = tabelle(fremdSkala);
}
setzeTheme();
function themaWechsel() {
  if (mediaHell.matches === HELL) return;
  setzeTheme();
  glowSprites.fill(null);        // Sprites tragen die Momentum-Farben des alten Schemas
  farbenAktualisieren();
  draw();
}
mediaHell.addEventListener("change", themaWechsel);
const QUELLE_FARBEN = (G && G.source_colors) || {};
const QUELLE_H = {};   // Farbton je Quelle im Bogenmaß, für die HSV-Mischung
for (const [s, c] of Object.entries(QUELLE_FARBEN)) QUELLE_H[s] = d3.hsl(c).h * Math.PI / 180;

function lsGet(k) { try { return localStorage.getItem(k); } catch { return null; } }
function lsSet(k, v) { try { localStorage.setItem(k, v); } catch {} }

/* ---------- Zustand ---------- */

let farbmix = lsGet("map_farbmix") === "single" ? "single" : "mix";
// Abstoßungskraft (forceManyBody-Stärke) — per Settings-Regler einstellbar, gemerkt.
let repulsion = Math.min(400, Math.max(60, +lsGet("map_repulsion") || ABSTOSSUNG_VORGABE));

let nodes = [], links = [], nachbarn = [], sim = null;
let labelFolge = [];       // Knoten nach Artikelzahl absteigend, für die Label-Vergabe
let signatur = 0;          // erkennt einen neu gebauten Datensatz im Layout-Cache
let MOM = new Uint8Array(0), NW = 1, WIN = 4, startMs = Date.now(), wochen = [""];
const MS_WEEK = 7 * 24 * 3600 * 1000;
let pos = 0;               // gebrochene Wochenposition → weiche Zeitraffer-Übergänge
let animPhase = 0;         // läuft nur während der Wiedergabe → dezentes Pulsieren
let spielend = false;
let modus = "cluster";
let hover = null, auswahl = null;
let benutzerAktiv = false;   // sobald der Nutzer zoomt/zieht, folgt die Kamera nicht mehr
let transform = d3.zoomIdentity;
let redrawGeplant = false;

// Feste Werte der Darstellung, eingestellt im Konzept (concepts/karten_layout); die Kräfte
// stehen in map_layout.js
const LABEL_AB = 4;          // Beschriftung, sobald ein Knoten größer als so viele Pixel gezeichnet ist
const SLOTS = 30;            // freie Plätze für Keywords, die die Suche vom NAS holt

/* ============================================================================
   Kugel-Projektion

   Der Unterschied zur Ebene ist nicht nur die Darstellung: Dort liefert UMAP die
   Startlage und ein Kraft-Layout im Browser macht daraus die Karte, hier ist die Lage
   fertig (node.xyz, auf dem Mac gerechnet) und wird nur noch gedreht. Der Grund ist
   gemessen — auf der Kugel gibt es keinen Rand, gegen den eine Abstoßung drückt, also
   schiebt sie weiter, bis alles gleichverteilt ist, und gleichverteilt heißt
   strukturlos (Top-10-Nachbarschaftstreue 0,45 -> 0,24).

   Dadurch gibt es hier weder Simulation noch Layout-Cache: Die Karte steht, sobald die
   Daten da sind.
   ============================================================================ */

const TAU2 = Math.PI * 2;
const klemm = (v, a, b) => v < a ? a : v > b ? b : v;

let projektion = lsGet("map_projektion") === "kugel" ? "kugel" : "flach";
let hatKugel = false;        // Datensatz ohne node.xyz -> nur Ebene möglich
let P = null;                // Float64Array 3n, Lage auf der Einheitskugel

// Kamera wie beim Globus (web/globe.js): Längen-/Breitenwinkel plus Radius in Bildpunkten.
let lam = 0, phi = 0, R = 300, R0 = 300;
let vlam = 0, vphi = 0;      // Schwung nach dem Loslassen
let zieht = false, laeuft = false, flug = null;
let letzteGeste = 0;
let drift = lsGet("map_drift") !== "aus";
let rueckseite = klemm(+lsGet("map_rueck") || 22, 0, 60) / 100;
const DRIFT_TEMPO = 0.035;   // rad/s — eine Umdrehung in rund drei Minuten
const DRIFT_PAUSE = 2500;    // ms Ruhe nach einer Geste, bevor die Drift wieder anläuft

// Knotengröße auf der Kugel flacher als in der Ebene (dort 2,2 + sqrt(Masse) × 0,55).
// Grund: Hier wissen Größe und Abstand nichts voneinander — in der Ebene kennt
// forceCollide die Radien und schiebt große Knoten selbst auseinander, auf der Kugel
// steht die Lage fest und ihr Sollabstand gilt für alle gleich. Die schwersten Keywords
// überrannten damit ihre Nachbarn und verschmolzen zu Flecken. Hoch 0,40 nimmt dem
// größten Knoten rund 30 % Radius und lässt die kleinen, wo sie waren.
const kugelRadius = m => 1.6 + Math.pow(m, 0.40) * 0.95;
const KNOTEN_BEZUG = 710;    // r × R / KNOTEN_BEZUG = Bildpunkte; größer heißt kleiner

/* ---------- Projektion ----------
   Orthografisch: Die Kamerabasis ist das Dreibein aus Ost, Nord und Blickrichtung an der
   Stelle (lam, phi); X/Y sind die Bildschirmachsen, Z die Tiefe (> 0 = Vorderseite). Pro
   Bild sechs Winkelfunktionen, danach neun Multiplikationen je Punkt. */

let ex = 0, ey = 0, nx = 0, ny = 0, nz = 0, cx3 = 0, cy3 = 0, cz3 = 0;
let CX = 0, CY = 0;
function kamera() {
  const cl = Math.cos(lam), sl = Math.sin(lam), cp = Math.cos(phi), sp = Math.sin(phi);
  ex = -sl;      ey = cl;                   // Ost (ez ist immer 0)
  nx = -sp * cl; ny = -sp * sl; nz = cp;    // Nord
  cx3 = cp * cl; cy3 = cp * sl; cz3 = sp;   // Blickrichtung
}

let SX = new Float32Array(0), SY = new Float32Array(0), SZ = new Float32Array(0);
function projiziereKnoten() {
  for (let i = 0; i < nodes.length; i++) {
    const x = P[3*i], y = P[3*i+1], z = P[3*i+2];
    SX[i] = CX + R * (x * ex + y * ey);
    SY[i] = CY - R * (x * nx + y * ny + z * nz);
    SZ[i] = x * cx3 + y * cy3 + z * cz3;
  }
}

/* ---------- Kanten als Großkreisbögen ----------
   Eine Kante zwischen zwei Punkten der Kugel ist der Großkreis zwischen ihnen, nicht die
   gerade Bildschirmlinie: Die liefe *durch* die Kugel und käme bei langen Kanten auf der
   falschen Seite heraus. Gemessen sind 12 % aller Kanten länger als 0,5 rad, die längste
   2,84 rad — also fast von Pol zu Pol.

   Die Stützpunkte hängen nur an der festen Lage, nicht an der Kamera: einmal in
   Weltkoordinaten aufgeteilt, danach wie Knoten projiziert. Schrittweite 0,12 rad — der
   Pfeilhöhenfehler eines Segments ist R·w²/8, bei R = 400 also 0,7 Bildpunkte. */

const BOGEN_SCHRITT = 0.12;
let BV = new Float64Array(0);
let BSX = new Float32Array(0), BSY = new Float32Array(0), BSZ = new Float32Array(0);
let kantenStart = new Int32Array(0), kantenZahl = new Int32Array(0);
let kantenBogen = new Float32Array(0), kantenStufe = new Uint8Array(0);

const K_STUFEN = 7;          // Stärkestufen der Kanten (Gewicht × Längendämpfung)
const T_STUFEN = 4;          // Tiefenstufen der Vorderseite
// Eine Kante, die halb um die Kugel läuft, ist keine starke Verbindung, sondern eine, die
// das Layout nicht einlösen konnte. Das Gewicht trägt das nicht (Rangzusammenhang Bogen
// zu Gewicht nur -0,35); ohne die Dämpfung spannen die langen Kanten ein Netz quer über
// die Kugel und überdecken genau die dichte Nachbarschaft, um die es geht.
const BOGEN_HALB = 0.35;

function baueBoegen() {
  const m = links.length;
  kantenStart = new Int32Array(m); kantenZahl = new Int32Array(m);
  kantenBogen = new Float32Array(m); kantenStufe = new Uint8Array(m);
  let gesamt = 0;
  for (let e = 0; e < m; e++) {
    const a = links[e].source.i, b = links[e].target.i;
    const w = Math.acos(klemm(P[3*a]*P[3*b] + P[3*a+1]*P[3*b+1] + P[3*a+2]*P[3*b+2], -1, 1));
    kantenBogen[e] = w;
    const gew = G.mix ? links[e].z : klemm((links[e].w - 0.55) / 0.45, 0, 1);
    const q = w / BOGEN_HALB;
    kantenStufe[e] = Math.min(K_STUFEN - 1,
      Math.round(gew * gew / (1 + q * q) * (K_STUFEN - 1)));
    const seg = Math.max(1, Math.ceil(w / BOGEN_SCHRITT));
    kantenStart[e] = gesamt; kantenZahl[e] = seg + 1;
    gesamt += seg + 1;
  }
  BV = new Float64Array(gesamt * 3);
  BSX = new Float32Array(gesamt); BSY = new Float32Array(gesamt); BSZ = new Float32Array(gesamt);
  for (let e = 0; e < m; e++) {
    const a = links[e].source.i, b = links[e].target.i, w = kantenBogen[e];
    const seg = kantenZahl[e] - 1, si = Math.sin(w);
    for (let k = 0; k <= seg; k++) {
      const t = k / seg;
      let f0, f1;
      if (si > 1e-6) { f0 = Math.sin((1 - t) * w) / si; f1 = Math.sin(t * w) / si; }
      else { f0 = 1 - t; f1 = t; }   // winziger Bogen: linear und normieren
      const x = f0 * P[3*a] + f1 * P[3*b];
      const y = f0 * P[3*a+1] + f1 * P[3*b+1];
      const z = f0 * P[3*a+2] + f1 * P[3*b+2];
      const l = Math.hypot(x, y, z) || 1;
      const o = (kantenStart[e] + k) * 3;
      BV[o] = x / l; BV[o+1] = y / l; BV[o+2] = z / l;
    }
  }
  return gesamt;
}

function projiziereBoegen() {
  for (let i = 0; i < BSX.length; i++) {
    const x = BV[3*i], y = BV[3*i+1], z = BV[3*i+2];
    BSX[i] = CX + R * (x * ex + y * ey);
    BSY[i] = CY - R * (x * nx + y * ny + z * nz);
    BSZ[i] = x * cx3 + y * cy3 + z * cz3;
  }
}

/* ---------- Zeichnen auf der Kugel ----------
   Zwei Durchgänge nach Tiefe: erst die Rückseite in *einem* flachen Grau, dann die
   Vorderseite. Wäre die Rückseite normal sichtbar, schiene sie von hinten durch und man
   läse zwei Ebenen übereinander. Innerhalb der Vorderseite steuert die Tiefe nur die
   Deckkraft, gestuft — sonst käme je Knoten ein eigener Zeichenaufruf. */

const vorne = z => klemm((z + 0.04) / 0.20, 0, 1);
const tstufe = f => Math.min(T_STUFEN - 1, (f * T_STUFEN) | 0);
const radius3d = d => d.r3 * (R / KNOTEN_BEZUG)
  * (modus === "momentum" ? 0.85 + 0.55 * mom(d) : 1);

const kantenEimer = [];
function zeichne3d() {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = T.bg;
  ctx.fillRect(0, 0, W, H);
  if (!W || !nodes.length || !P) { ctx.globalAlpha = 1; return; }
  kamera(); projiziereKnoten(); projiziereBoegen();
  // Nachbarschaft hervorheben nur nach Klick (auswahl); die Maus darüber bekommt bloß
  // den Ring und den Tooltip — sonst blendet jede Bewegung die ganze Karte aus.
  const ring = hover ?? auswahl;
  const aktiv = aktiveMenge(auswahl);
  if (rueckseite > 0) { kantenRueck3d(); knotenRueck3d(); }
  kantenVorn3d(aktiv);
  if (modus === "momentum") glow3d(aktiv);
  knotenVorn3d(aktiv, ring);
  labels3d(aktiv);
  ctx.globalAlpha = 1;
}

// Sichtfenster in Bildschirmkoordinaten — beim Hineinzoomen liegt das meiste außerhalb.
const RAND = 80;
const drin = (x0, y0, x1, y1) =>
  !((x0 < -RAND && x1 < -RAND) || (x0 > W + RAND && x1 > W + RAND) ||
    (y0 < -RAND && y1 < -RAND) || (y0 > H + RAND && y1 > H + RAND));

function kantenRueck3d() {
  ctx.strokeStyle = T.kanteRueck;
  ctx.lineWidth = 1;
  ctx.globalAlpha = 0.34 * rueckseite;
  ctx.beginPath();
  for (let e = 0; e < links.length; e++) {
    // Die schwächsten Kanten bleiben hinten ganz weg: dort zählt nur, dass ein Geflecht
    // da ist, und in einem Zug gezeichnet addiert sich ihre Deckkraft ohnehin nicht.
    if (kantenStufe[e] === 0 || links[e].source.weg || links[e].target.weg) continue;
    const s = kantenStart[e], n = kantenZahl[e];
    for (let k = 0; k < n - 1; k++) {
      const i = s + k, j = i + 1;
      if (BSZ[i] + BSZ[j] >= 0) continue;
      if (!drin(BSX[i], BSY[i], BSX[j], BSY[j])) continue;
      ctx.moveTo(BSX[i], BSY[i]); ctx.lineTo(BSX[j], BSY[j]);
    }
  }
  ctx.stroke();
  ctx.globalAlpha = 1;
}

function knotenRueck3d() {
  ctx.fillStyle = T.knotenRueck;
  ctx.globalAlpha = 0.55 * rueckseite;
  ctx.beginPath();
  for (const d of nodes) {
    if (d.weg || SZ[d.i] >= 0) continue;
    const r = radius3d(d) * 0.7;
    if (!drin(SX[d.i] - r, SY[d.i] - r, SX[d.i] + r, SY[d.i] + r)) continue;
    ctx.moveTo(SX[d.i] + r, SY[d.i]);
    ctx.arc(SX[d.i], SY[d.i], r, 0, TAU2);
  }
  ctx.fill();
  ctx.globalAlpha = 1;
}

// Vorderseite: ein Pfad je (Stärkestufe × Tiefenstufe), also höchstens 28 stroke()-Aufrufe
// für rund 30 000 Segmente.
function kantenVorn3d(aktiv) {
  const grund = Math.min(0.85, 4000 / Math.max(1, links.length));
  const daempfung = aktiv ? 0.10 : themaSet ? 0.30 : 1;
  for (let i = 0; i < K_STUFEN * T_STUFEN; i++) (kantenEimer[i] || (kantenEimer[i] = [])).length = 0;
  for (let e = 0; e < links.length; e++) {
    if (links[e].source.weg || links[e].target.weg) continue;
    const s = kantenStart[e], n = kantenZahl[e], ks = kantenStufe[e];
    for (let k = 0; k < n - 1; k++) {
      const i = s + k, j = i + 1, zm = (BSZ[i] + BSZ[j]) / 2;
      if (zm < 0) continue;
      if (!drin(BSX[i], BSY[i], BSX[j], BSY[j])) continue;
      kantenEimer[ks * T_STUFEN + tstufe(vorne(zm))].push(i);
    }
  }
  ctx.globalCompositeOperation = T.kantenModus;
  ctx.strokeStyle = T.kante;
  for (let ks = 0; ks < K_STUFEN; ks++) {
    ctx.lineWidth = 0.5 + 2.0 * ks / (K_STUFEN - 1);
    // hoch 1,3 statt linear: mit "lighter" addieren sich die vielen schwachen Kanten
    // sonst zu einem gleichmäßigen Schleier über der ganzen Scheibe
    const gw = Math.max(0.02, (ks / (K_STUFEN - 1)) ** 1.3) * grund * T.kantenFaktor;
    for (let ts = 0; ts < T_STUFEN; ts++) {
      const liste = kantenEimer[ks * T_STUFEN + ts];
      if (!liste.length) continue;
      ctx.globalAlpha = gw * (0.30 + 0.70 * (ts + 0.5) / T_STUFEN) * daempfung;
      ctx.beginPath();
      for (const i of liste) { ctx.moveTo(BSX[i], BSY[i]); ctx.lineTo(BSX[i+1], BSY[i+1]); }
      ctx.stroke();
    }
  }
  const hell = aktiv ?? themaSet;
  if (hell) {
    ctx.globalAlpha = 0.85; ctx.beginPath();
    for (let e = 0; e < links.length; e++) {
      if (!hell.has(links[e].source.i) || !hell.has(links[e].target.i)) continue;
      const s = kantenStart[e], n = kantenZahl[e];
      for (let k = 0; k < n - 1; k++) {
        const i = s + k;
        if (BSZ[i] + BSZ[i+1] < 0) continue;
        ctx.moveTo(BSX[i], BSY[i]); ctx.lineTo(BSX[i+1], BSY[i+1]);
      }
    }
    ctx.stroke();
  }
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = 1;
}

const knotenEimer3d = new Map();
function knotenVorn3d(aktiv, fokus) {
  const grund = aktiv ? 0.10 : 0.94;
  for (const arr of knotenEimer3d.values()) arr.length = 0;
  for (const d of nodes) {
    const z = SZ[d.i];
    if (d.weg || z < 0) continue;
    const r = radius3d(d) * (0.78 + 0.22 * z);
    if (!drin(SX[d.i] - r, SY[d.i] - r, SX[d.i] + r, SY[d.i] + r)) continue;
    const schluessel = (farbeJeKnoten[d.i] ?? farbe(d)) + "|" + tstufe(vorne(z));
    let arr = knotenEimer3d.get(schluessel);
    if (!arr) knotenEimer3d.set(schluessel, arr = []);
    arr.push(d);
  }
  for (const [schluessel, liste] of knotenEimer3d) {
    if (!liste.length) continue;
    const trenn = schluessel.lastIndexOf("|");
    const f = schluessel.slice(0, trenn), ts = +schluessel.slice(trenn + 1);
    ctx.fillStyle = f;
    ctx.globalAlpha = grund * (0.35 + 0.65 * (ts + 0.5) / T_STUFEN)
      * (themaSet && f === THEMA_GRAU ? 0.5 : 1);
    ctx.beginPath();
    for (const d of liste) {
      const r = radius3d(d) * (0.78 + 0.22 * SZ[d.i]);
      ctx.moveTo(SX[d.i] + r, SY[d.i]);
      ctx.arc(SX[d.i], SY[d.i], r, 0, TAU2);
    }
    ctx.fill();
  }
  if (aktiv) {
    ctx.globalAlpha = 0.95;
    for (const i of aktiv) {
      if (SZ[i] < 0 || nodes[i].weg) continue;
      const d = nodes[i], r = radius3d(d) * (0.78 + 0.22 * SZ[i]);
      ctx.fillStyle = farbeJeKnoten[i] ?? farbe(d);
      ctx.beginPath(); ctx.arc(SX[i], SY[i], r, 0, TAU2); ctx.fill();
    }
  }
  if (fokus && !fokus.weg && SZ[fokus.i] >= 0) {
    ctx.globalAlpha = 1; ctx.lineWidth = 1.6; ctx.strokeStyle = T.fokusRing;
    ctx.beginPath();
    ctx.arc(SX[fokus.i], SY[fokus.i],
            radius3d(fokus) * (0.78 + 0.22 * SZ[fokus.i]) + 1.5, 0, TAU2);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

function glow3d(aktiv) {
  ctx.globalCompositeOperation = T.glowModus;
  for (const d of nodes) {
    const m = mom(d);
    if (d.weg || SZ[d.i] < 0 || m < 0.06 || (aktiv && !aktiv.has(d.i)) || fremdesThema(d)) continue;
    const gr = radius3d(d) * (2.4 + 3.2 * m);
    if (!drin(SX[d.i] - gr, SY[d.i] - gr, SX[d.i] + gr, SY[d.i] + gr)) continue;
    const puls = spielend ? 0.82 + 0.18 * Math.sin(animPhase * 4 + d.i) : 1;
    ctx.globalAlpha = 0.55 * m * puls * vorne(SZ[d.i]);
    ctx.drawImage(glowSprite(Math.round(m * (GLOW_STUFEN - 1))),
                  SX[d.i] - gr, SY[d.i] - gr, gr * 2, gr * 2);
  }
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = 1;
}

/* Labels: dieselbe Platzvergabe wie in der Ebene (Rechteck gegen Rechteck, Raster nur als
   Index). Neu ist die Reihenfolge — auf einer Kugel entscheidet nicht die Artikelzahl
   allein, wer ein Label bekommt, sondern auch, wie weit vorn der Knoten steht. Sortierte
   man je Bild nach der Tiefe selbst, wechselte die Rangfolge bei jeder Winzigkeit und die
   Labels flackerten; darum grobe Tiefenbänder und innerhalb eines Bandes die feste
   Artikelzahl. */
const LABEL_BAENDER = 5;
const LABEL_BUDGET = 350;
function labels3d(aktiv) {
  ctx.globalAlpha = 1;
  ctx.textAlign = "center";
  zellen.clear();
  const skala = R / KNOTEN_BEZUG;
  labelFolge.sort((a, b) =>
    (Math.min(LABEL_BAENDER - 1, (vorne(SZ[b.i]) * LABEL_BAENDER) | 0)
     - Math.min(LABEL_BAENDER - 1, (vorne(SZ[a.i]) * LABEL_BAENDER) | 0)) || (b.n - a.n));
  // Nicht die Knotengröße begrenzt die Kandidaten, sondern ihre Zahl. Die Schriftgröße
  // ist bei 10,5 px ohnehin gedeckelt, ein Radius-Schwellwert wäre also kein Lesbarkeits-
  // sondern ein Wichtigkeitsfilter — und als solcher hängt er am Kugelradius: derselbe
  // Wert ließ auf dem iPhone 4 Labels übrig und am Rechner über tausend zu. Ein festes
  // Budget hält Dichte und Kosten über alle Bildschirmgrößen und Zoomstufen gleich;
  // labelFolge ist bereits nach Tiefenband und Artikelzahl sortiert, die ersten sind
  // also die wichtigsten.
  let kandidaten = 0;
  for (const d of labelFolge) {
    const z = SZ[d.i];
    if (d.weg || z < 0.05) continue;
    if (aktiv ? !aktiv.has(d.i) : themaSet && !themaSet.has(d.i)) continue;
    if (!aktiv && ++kandidaten > LABEL_BUDGET) break;
    const r = d.r3 * skala;
    const px = SX[d.i], py = SY[d.i] - r - 4;
    if (!(Math.abs(px) < 1e6 && Math.abs(py) < 1e6)) continue;
    const fs = Math.round(Math.min(15, Math.max(10.5, r * 0.55)) * 2) / 2;
    const halb = halbeBreite(d.id, fs) + 3;
    if (!platzNehmen(px - halb, py - fs, px + halb, py + 4)) continue;
    if (px + halb < 0 || px - halb > W || py + 4 < 0 || py - fs > H) continue;
    ctx.globalAlpha = klemm((z - 0.05) / 0.22, 0, 1);
    ctx.font = schrift(fs);
    ctx.fillStyle = T.labelHalo;
    ctx.fillText(d.id, px, py + 1);
    ctx.fillStyle = aktiv ? T.labelText : T.labelDim;
    ctx.fillText(d.id, px, py);
  }
  ctx.globalAlpha = 1;
}

/* ---------- Bewegung ---------- */

function anstossen() {
  if (laeuft || projektion !== "kugel") return;
  laeuft = true;
  requestAnimationFrame(takt);
}
let letzterTakt = 0;
function takt(ts) {
  if (projektion !== "kugel") { laeuft = false; letzterTakt = 0; return; }
  const dt = letzterTakt ? Math.min(0.05, (ts - letzterTakt) / 1000) : 0.016;
  letzterTakt = ts;
  let bewegt = false;
  if (flug) {
    flug.t = Math.min(1, flug.t + dt / flug.dauer);
    const e = flug.t < .5 ? 4 * flug.t ** 3 : 1 - (-2 * flug.t + 2) ** 3 / 2;   // easeInOutCubic
    lam = flug.l0 + flug.dl * e;
    phi = flug.p0 + flug.dp * e;
    if (flug.dr) R = flug.r0 + flug.dr * e;
    if (flug.t >= 1) flug = null;
    bewegt = true;
  } else if (!zieht) {
    if (Math.abs(vlam) > 1e-5 || Math.abs(vphi) > 1e-5) {
      lam += vlam; phi = klemm(phi + vphi, -1.45, 1.45);
      vlam *= 0.93; vphi *= 0.93;
      bewegt = true;
    } else if (drift && performance.now() - letzteGeste > DRIFT_PAUSE) {
      lam += DRIFT_TEMPO * dt;
      bewegt = true;
    }
  }
  // Der Zeitraffer zeichnet über seinen eigenen Takt weiter, auch wenn nichts rotiert.
  if (bewegt || zieht) { zeichne3d(); requestAnimationFrame(takt); }
  else { laeuft = false; letzterTakt = 0; }
}

// Einen Knoten in die Bildmitte drehen: seine Weltlage IST die Kamerarichtung, aus der
// sich lam/phi direkt ablesen lassen. Über den Längenkreis wird der kürzere Weg genommen.
function drehZu(d, dauer = 0.65, zoom = 0) {
  const x = P[3*d.i], y = P[3*d.i+1], z = P[3*d.i+2];
  flug = { t: 0, dauer, l0: lam, p0: phi,
           dl: ((Math.atan2(y, x) - lam + Math.PI * 3) % TAU2) - Math.PI,
           dp: klemm(Math.asin(klemm(z, -1, 1)), -1.45, 1.45) - phi,
           r0: R, dr: zoom ? klemm(zoom, R0 * 0.6, R0 * 14) - R : 0 };
  letzteGeste = performance.now();
  anstossen();
}

function setzeRadius(r) { R = klemm(r, R0 * 0.6, R0 * 14); }

// Nur Knoten der Vorderseite sind Ziele — was hinten liegt, ist ohnehin kaum zu sehen.
function knotenBei3d(px, py) {
  let best = null, bd = 22;
  for (const d of nodes) {
    if (d.weg || SZ[d.i] < 0) continue;
    const dist = Math.hypot(SX[d.i] - px, SY[d.i] - py) - radius3d(d);
    if (dist < bd) { bd = dist; best = d; }
  }
  return best;
}

function momAt(i, p) {
  if (!NW) return 0;
  const w0 = Math.max(0, Math.min(NW - 1, Math.floor(p)));
  const w1 = Math.min(NW - 1, w0 + 1), f = p - w0;
  return (MOM[i * NW + w0] * (1 - f) + MOM[i * NW + w1] * f) / 255;
}
const mom = d => momAt(d.i, pos);

// Quellen-Farbe: entweder dominante Quelle (einfarbig) oder HSV-Mischung — die Farbtöne
// der Quellen werden als Vektoren auf dem Farbkreis mit ihren Anteilen gemittelt.
// Konzentriert auf eine Quelle = kräftige Quellenfarbe, gleichmäßig verteilt = blass/weißlich.
function quellenFarbe(d) {
  if (farbmix !== "mix" || !d.sw) return QUELLE_FARBEN[d.src] || OHNE_WERT;
  let vx = 0, vy = 0, tot = 0;
  for (const s in d.sw) {
    if (!(s in QUELLE_H)) continue;
    const a = d.sw[s];
    vx += a * Math.cos(QUELLE_H[s]); vy += a * Math.sin(QUELLE_H[s]); tot += a;
  }
  if (!tot) return OHNE_WERT;
  const mag = Math.hypot(vx, vy) / tot;
  const hue = (Math.atan2(vy, vx) * 180 / Math.PI + 360) % 360;
  return d3.hsl(hue, 0.15 + 0.75 * mag, T.hellwert(mag)) + "";
}

// Keywords, die keinem Thema nahe genug kommen, tragen cluster -1 und bleiben grau —
// eine Farbe zu vergeben täuschte eine Zuordnung vor, die es nicht gibt.
const themenFarbe = c => c < 0 ? KEIN_THEMA : PALETTE[c % PALETTE.length];

// Themen-Fokus (Klick in der Legende): die Region soll sich abheben, ohne dass die übrige
// Karte verschwindet — ein einziges Grau für alles andere, damit die Form als Kontext
// stehen bleibt. Weil alle fremden Knoten dieselbe Farbe tragen, fallen sie in einen
// einzigen Zeichen-Eimer; der Fokus kostet also nichts.
let themaFokus = null, themaSet = null;
const fremdesThema = d => themaFokus !== null && d.cluster !== themaFokus;

function farbe(d) {
  if (fremdesThema(d)) return THEMA_GRAU;
  // ohne Einfärbung trägt nur ein in der Legende gewähltes Thema seine Farbe
  if (modus === "keine") return themaFokus !== null ? themenFarbe(d.cluster) : NEUTRAL;
  if (modus === "cluster") return themenFarbe(d.cluster);
  if (modus === "similar") return d.col || KEIN_THEMA;   // Karten vor dieser Fassung: grau
  if (modus === "fremd") return FREMD_LUT[(fremdAnteil(d.i) * 255) | 0];
  if (modus === "like") return d.like === null ? OHNE_WERT : LIKE_LUT[(d.like * 255) | 0];
  if (modus === "streuung") return d.streu == null ? OHNE_WERT : LIKE_LUT[((1 - streuRang(d.streu)) * 255) | 0];
  if (modus === "momentum") return MOM_LUT[(mom(d) * 255) | 0];
  return quellenFarbe(d);
}
function radius(d) {
  return modus === "momentum" ? d.r * (0.85 + 0.55 * mom(d)) : d.r;
}

const LEGENDEN = {
  cluster: "Colour = topic, grey = none · Size = article count",
  similar: "Colour = meaning itself: alike keywords get alike colours, wherever they sit · "
         + "a lone colour among its neighbours is a keyword that only landed there",
  fremd: "Red = this keyword has little in common with the six nodes closest to it — "
       + "it sits there by accident of the layout, not by topic",
  like: "Red = disliked · Green = liked · Grey = too few ratings",
  streuung: "Red = its articles scatter over many contexts · Green = always the same context · ranked within the map",
  keine: "No colouring · tap a mode above to colour the map again",
  momentum: "Golden glow = unusually active topic · Faint = quiet · ▶ plays the timelapse",
};
// Die Bediensätze unterscheiden sich: Die Ebene wird geschoben, die Kugel gedreht.
const BEDIENUNG = () => projektion === "kugel"
  ? " · Drag to rotate, scroll to zoom"
  : " · Scroll to zoom, drag to pan";
function legendeText(m) {
  if (m !== "quelle") return LEGENDEN[m] + (m === "cluster" ? BEDIENUNG() : "");
  const chips = Object.entries(QUELLE_FARBEN).map(([s, c]) =>
    `<span style="color:${esc(c)}">■</span> ${esc(s)}`).join(" · ");
  return (farbmix === "mix"
    ? "Hue = blend of the sources · pale = evenly shared · "
    : "Colour = dominant source of the topic · ") + chips;
}

/* ---------- Kamera ---------- */

const zoomSel = d3.select(canvas);
// Untergrenze deutlich unter dem eingepassten Maßstab (bei 1000 Knoten auf dem iPhone
// rund 0,12) — sonst rastet die erste Nutzergeste sichtbar auf die Untergrenze ein.
const zoom = d3.zoom()
  .scaleExtent([0.04, 12])
  .on("zoom", e => {
    if (e.sourceEvent) benutzerAktiv = true;
    transform = e.transform;
    render();
  });
zoomSel.call(zoom).call(zoom.transform, transform);
const setzeKamera = t => zoomSel.call(zoom.transform, t);

// Kamera auf die Punktwolke: 2-/98-Perzentil, damit einzelne Ausreißer die Karte nicht
// kleinrechnen. Läuft bei jedem Tick, solange der Nutzer die Karte nicht selbst bewegt
// hat: die Punktwolke behält so ihre Bildschirmgröße, während sich das Layout auseinander
// schiebt. Vorher passte die Kamera nur alle 15 Ticks ein — das war das sichtbare Zappeln
// (der erste Sprung allein änderte den Maßstab um mehr als das Vierfache).
let fitX = null, fitY = null;
function einpassen() {
  // nur sichtbare: Ausgeblendete liegen im Ursprung und zögen die Quantile dorthin
  const quelle = sim ? sim.nodes() : nodes.filter(d => !d.weg);
  if (!quelle.length || !W) return;
  const schritt = quelle.length > 400 ? 3 : 1;   // Stichprobe reicht für Perzentile
  const n = Math.ceil(quelle.length / schritt);
  if (!fitX || fitX.length !== n) { fitX = new Float64Array(n); fitY = new Float64Array(n); }
  for (let i = 0, j = 0; j < n; i += schritt, j++) { fitX[j] = quelle[i].x; fitY[j] = quelle[i].y; }
  fitX.sort(); fitY.sort();
  const q = (a, p) => a[Math.round((a.length - 1) * p)];
  const x0 = q(fitX, .02), x1 = q(fitX, .98), y0 = q(fitY, .02), y1 = q(fitY, .98);
  // *0.82: etwas herauszoomen, damit die Karte nicht am Rand abgeschnitten wird
  const k = Math.min(W / (x1 - x0 + 120), H / (y1 - y0 + 120), 3) * 0.82;
  if (!(k > 0) || !isFinite(k)) return;
  setzeKamera(d3.zoomIdentity
    .translate(W / 2 - (x0 + x1) / 2 * k, H / 2 - (y0 + y1) / 2 * k)
    .scale(k));
}

function springeZu(d) {
  if (projektion === "kugel") { drehZu(d, 0.65, Math.max(R, R0 * 2.2)); return; }
  benutzerAktiv = true;
  const k = Math.max(transform.k, 2.5);
  const t = d3.zoomIdentity.translate(W / 2 - d.x * k, H / 2 - d.y * k).scale(k);
  zoomSel.transition().duration(600).call(zoom.transform, t);
}

let resizeGeplant = false;
addEventListener("resize", () => {
  if (resizeGeplant) return;
  resizeGeplant = true;
  requestAnimationFrame(() => { resizeGeplant = false; resize(); });
});
// Die App blendet den Karten-iframe beim Tab-Wechsel nur aus (display:none) und meldet
// sich beim Einblenden zurück — dann ist die Größe wieder messbar.
addEventListener("message", e => {
  // Beim Einblenden auch das Farbschema prüfen: das change-Ereignis erreicht einen
  // versteckten iframe nicht zuverlässig (iOS wechselt abends von selbst auf Dunkel).
  if (e.origin === location.origin && e.data === "karte:sichtbar") { themaWechsel(); resize(); }
});
function resize() {
  const w = innerWidth, h = innerHeight;
  const d = Math.min(2, window.devicePixelRatio || 1);
  if (w < 2 || h < 2) return;   // ausgeblendet: Zustand unangetastet lassen
  if (w === W && h === H && d === dpr) return;
  // Weltpunkt in der Bildschirmmitte festhalten (Gerät drehen, iOS-Adressleiste)
  const mitte = W ? transform.invert([W / 2, H / 2]) : null;
  W = w; H = h; dpr = d;
  canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
  canvas.style.width = W + "px"; canvas.style.height = H + "px";
  // Kugel: Mittelpunkt und Grundradius neu setzen, den Zoomfaktor des Nutzers behalten.
  const faktor = R0 ? R / R0 : 1;
  CX = W / 2; CY = H / 2;
  R0 = Math.min(W, H) * 0.46;
  R = R0 * faktor;
  if (!nodes.length) { render(); return; }
  if (projektion === "kugel") { render(); return; }
  if (benutzerAktiv && mitte) {
    setzeKamera(d3.zoomIdentity
      .translate(W / 2 - mitte[0] * transform.k, H / 2 - mitte[1] * transform.k)
      .scale(transform.k));
  } else {
    einpassen();
  }
  render();
}

/* ---------- Daten nach Bedarf ----------
   Die Seite trägt nur den Kern: Namen, Größe, Thema, Startlage, Kanten. Alles Weitere kommt
   beim ersten Gebrauch als Paket (keyword_map._teilen), die typischen Artikel je Knoten. Die
   Adresse trägt die Prüfsumme des Pakets: Der Browser darf es dauerhaft halten, und ein
   Paket aus einem neueren Bau (409) heißt, die Seite ist veraltet und lädt neu. */
const teilDa = new Set();
const teilLaeuft = {};
const TEIL_ANWENDEN = {
  details: liste => { felderUebernehmen(liste); streuRangNeu(); },
  kugel: liste => { felderUebernehmen(liste.map(xyz => ({ xyz }))); slotsAufKugel(); },
  momentum: m => { G.momentum = m; momentumAnwenden(); },
  vektoren: v => { G.fit = v.fit; G.kooc = v.kooc; vektorenAnwenden(); },
};
async function holeJson(url) {
  const r = await fetch(url);
  if (r.status === 409) { location.reload(); throw new Error("map rebuilt"); }
  if (!r.ok) throw new Error(String(r.status));
  return r.json();
}
function teil(name) {
  if (teilDa.has(name) || !(G.teile && G.teile[name])) return Promise.resolve();
  return teilLaeuft[name] ??= holeJson(`api/map_teil/${name}?h=${G.teile[name]}`)
    .then(daten => { TEIL_ANWENDEN[name](daten); teilDa.add(name); })
    .finally(() => { delete teilLaeuft[name]; });
}
function felderUebernehmen(liste) {
  liste.forEach((f, i) => { Object.assign(G.nodes[i], f); if (nodes[i]) Object.assign(nodes[i], f); });
}
const artikelLaeuft = new Map();
function artikelLaden(d) {
  if (d.art) return Promise.resolve(d.art);
  if (!artikelLaeuft.has(d.i)) artikelLaeuft.set(d.i,
    holeJson(`api/map_artikel?h=${G.teile.artikel}&i=${d.i}`)
      .then(art => { G.nodes[d.i].art = art; if (nodes[d.i]) nodes[d.i].art = art; return art; })
      .finally(() => artikelLaeuft.delete(d.i)));
  return artikelLaeuft.get(d.i);
}

/* ---------- Graph aufbauen ---------- */

// Die Simulation startet immer aus der UMAP-Lage und landet damit fast am selben Ort — Zufall
// greift nur bei nahezu deckungsgleichen Knoten (gemessen im Median 30 px auf 31 000 px
// Kartenbreite). Ein fertiges Layout lohnt sich deshalb zu teilen: Es kommt aus dem
// Gerätespeicher, sonst aus der Datenbank — vom Mac beim Bau vorgerechnet oder von einem
// anderen Gerät abgelegt —, und erst wenn beides fehlt, rechnet dieses Gerät selbst und legt
// das Ergebnis dort ab. Gespeichert wird die Lage der Knoten des Datensatzes, ohne die freien
// Plätze der Suche.
let DATEN_N = 0;           // Knoten des Datensatzes; dahinter folgen die SLOTS freien Plätze
let lageLauf = 0;          // nur die jüngste Anfrage nach einer Lage zählt
let lageOffen = false;     // erste Lage noch unterwegs: nichts zeichnen statt der Startlage
function lageXY() {
  const xy = new Array(DATEN_N * 2);
  for (let i = 0; i < DATEN_N; i++) {
    xy[2 * i] = Math.round(nodes[i].x * 10) / 10;
    xy[2 * i + 1] = Math.round(nodes[i].y * 10) / 10;
  }
  return xy;
}
function layoutLaden() {
  try {
    const c = JSON.parse(lsGet("map_layout") || "null");
    if (!c || c.sig !== signatur || c.rep !== repulsion) return null;
    return c.xy.length === DATEN_N * 2 ? c.xy : null;
  } catch { return null; }
}
function layoutSichern(xy) { lsSet("map_layout", JSON.stringify({ sig: signatur, rep: repulsion, xy })); }
async function layoutVomServer() {
  const karte = G.settings && G.settings.built_at;
  if (!karte) return null;
  try {
    const r = await fetch(`api/map_layout?karte=${encodeURIComponent(karte)}`
      + `&version=${LAYOUT_VERSION}&rep=${repulsion}`);
    if (!r.ok) return null;
    const xy = await r.json();
    return Array.isArray(xy) && xy.length === DATEN_N * 2 ? xy : null;
  } catch { return null; }
}
// Ausgeblendetes läuft in der Simulation nicht mit — ein Layout ohne es gälte nicht für die
// übrigen Geräte.
function layoutTeilen(xy) {
  const karte = G.settings && G.settings.built_at;
  if (!karte || nodes.some(d => d.weg && !d.slot)) return;
  fetch("api/map_layout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ karte, version: LAYOUT_VERSION, rep: repulsion, xy }),
  }).catch(() => {});
}
function lageAnwenden(xy) {
  for (let i = 0; i < DATEN_N; i++) {
    const d = nodes[i];
    d.x = xy[2 * i]; d.y = xy[2 * i + 1]; d.vx = d.vy = 0;
  }
  // Eingefügtes kennt das Layout nicht (es gilt dem Datensatz): neu an die passende Stelle
  for (const i of slotDaten.keys()) platzieren(nodes[i], nodes.filter(x => !x.weg && !x.slot));
  sim.alpha(0);
  lageOffen = false; layoutFertig = true; fremd = null;
  benutzerAktiv = false;
  einpassen();
  farbenAktualisieren();
  render();
}
// `erstmals`: Die Startlage sagt nichts; bis die Lage feststeht, bleibt die Fläche leer. Beim
// Regler bleibt dagegen die bisherige Karte stehen, bis die neue da ist.
async function layoutBesorgen(erstmals) {
  const lauf = ++lageLauf;
  sim.stop();
  let xy = layoutLaden();
  if (!xy) {
    if (erstmals) { lageOffen = true; render(); }
    xy = await layoutVomServer();
    if (lauf !== lageLauf) return;
    if (xy) layoutSichern(xy);
  }
  if (xy) { lageAnwenden(xy); return; }
  try { await teil("vektoren"); } catch { /* bleibt unten bei der Startlage */ }
  if (lauf !== lageLauf) return;
  lageOffen = false;
  if (!FIT) { render(); return; }   // ohne Ähnlichkeit keine Unähnlichkeitskraft
  for (const d of sim.nodes()) { d.x = d.ux; d.y = d.uy; d.vx = d.vy = 0; }
  sim.force("charge").strength(-repulsion);
  layoutFertig = false; fremd = null;
  benutzerAktiv = false;
  sim.alpha(1).restart();
}

// Kanten gehören in die Signatur: Dieselben Keywords mit mehr oder anders gewichteten
// Kanten ergeben ein anderes Layout, und der Cache lieferte sonst das alte.
function baueSignatur() {
  let h = (G.nodes.length * 31 + LAYOUT_VERSION) | 0;
  for (const d of G.nodes) {
    if (d.slot) continue;   // Plätze der Suche ändern das Layout der Karte nicht
    for (let i = 0; i < d.id.length; i++) h = (h * 31 + d.id.charCodeAt(i)) | 0;
  }
  for (const l of G.links) {
    h = (h * 31 + l.s) | 0;
    h = (h * 31 + l.t) | 0;
    h = (h * 31 + Math.round(l.w * 1000)) | 0;
  }
  return h;
}

function momentumLaden() {
  const m = G.momentum;
  if (!m || !m.n || !m.b64) {   // Karte ohne Momentum-Daten bleibt bedienbar
    MOM = new Uint8Array(nodes.length); NW = 1; WIN = 4;
    startMs = Date.now(); wochen = [""];
    return;
  }
  const bin = atob(m.b64);
  if (bin.length % m.n || bin.length > nodes.length * m.n) {   // Daten passen nicht zu den Knoten
    MOM = new Uint8Array(nodes.length); NW = 1; WIN = 4;
    startMs = Date.now(); wochen = [""];
    return;
  }
  MOM = new Uint8Array(nodes.length * m.n);   // die freien Plätze der Suche bleiben leer
  for (let i = 0; i < bin.length; i++) MOM[i] = bin.charCodeAt(i);
  for (const [i, s] of slotDaten) MOM.set(s.mom.subarray(0, m.n), i * m.n);
  NW = m.n; WIN = m.win || 4;
  startMs = Date.parse(m.start + "T00:00:00Z");
  wochen = m.wochen || [];
}
function momentumAnwenden() {
  momentumLaden();
  pos = NW - 1; spielend = false; playBtn.textContent = "▶";
  slider.max = Math.max(0, NW - 1); slider.value = NW - 1;
  wochenlabel.textContent = wochen[NW - 1] || "";
  baueTicks();
}

// Fremdheit: mittlere Kosinus-Ähnlichkeit zu den FIT_K nächsten Knoten *im Layout*. Ein
// Wert nahe null heißt, dass ein Keyword nur zufällig dort liegt, wo es liegt. Muss hier
// gerechnet werden und nicht beim Kartenbau — welche Knoten benachbart sind, entscheidet
// erst das Kraft-Layout, und das ändert sich mit dem Abstoßungs-Regler.
const FIT_K = 6;
let fremd = null;        // Float32Array je Knoten, null = noch nicht gerechnet
let fremdRang = null;    // aufsteigend sortierte Kopie für die Perzentil-Skala

function vektorenAnwenden() {
  fitLaden(nodes.length);
  koocLaden(nodes.length);
  fremd = fremdRang = null;
  if (FIT) for (const [i, s] of slotDaten) FIT.set(s.vek, i * FIT.dim);
}

// Thematische Streuung (node.streu, im Kartenbau gerechnet) als Rang unter den Knoten der Karte
let streuSortiert = new Float64Array(0);
function streuRangNeu() {
  streuSortiert = Float64Array.from(nodes.filter(d => !d.weg && d.streu != null), d => d.streu).sort();
}
function streuRang(v) {
  let lo = 0, hi = streuSortiert.length;
  while (lo < hi) { const m = (lo + hi) >> 1; if (streuSortiert[m] < v) lo = m + 1; else hi = m; }
  return streuSortiert.length ? lo / streuSortiert.length : 0.5;
}

// Rund 1500² Abstände — warm wenige Millisekunden, darum roh statt mit räumlichem Index.
// Der Lauf passiert aber genau einmal je Layout und damit komplett im Interpreter:
// gemessen 134 ms kalt gegen 6 ms warm. Deshalb vorher ein paar Durchläufe auf einem
// Ausschnitt, das kostet nichts und bringt die Funktion auf Betriebstemperatur.
let fitWarm = false, layoutFertig = false;
function fremdheitRechnen() {
  // Vor dem Einschwingen liegen die Knoten noch dicht beieinander: die Nachbarschaft wäre
  // nicht die spätere, und die Suche findet kaum ein Abbruchkriterium (gemessen 140 statt
  // 6 ms). Bis das Layout steht, bleibt alles grau — das "end"-Ereignis rechnet nach.
  // Eigenes Kennzeichen statt sim.alpha(): sim.stop() senkt Alpha nicht, damit bliebe die
  // Karte nach einem Abbruch stumm grau.
  if (!FIT || !layoutFertig) {
    fremd = new Float32Array(nodes.length); fremdRang = fremd; return;
  }
  if (!fitWarm) {
    fitWarm = true;
    for (let i = 0; i < 8; i++) _fremdheit(Math.min(120, nodes.length));
  }
  fremd = _fremdheit(nodes.length);
  fremdRang = Float32Array.from(fremd).sort();
}

function _fremdheit(n) {
  const dim = FIT.dim;
  const raus = new Float32Array(n);
  const bestD = new Float64Array(FIT_K), bestI = new Int32Array(FIT_K);
  for (let a = 0; a < n; a++) {
    bestD.fill(Infinity); bestI.fill(-1);
    // Auf der Kugel zählt der Großkreisabstand; verglichen wird über das Skalarprodukt
    // (monoton gleichwertig, spart n² Arcuscosinus) und darum mit umgekehrtem Vorzeichen.
    const kugel = projektion === "kugel" && P;
    const ax = kugel ? P[3*a] : nodes[a].x, ay = kugel ? P[3*a+1] : nodes[a].y;
    const az = kugel ? P[3*a+2] : 0;
    for (let b = 0; b < n; b++) {
      if (b === a || nodes[b].weg) continue;
      const d2 = kugel
        ? -(ax * P[3*b] + ay * P[3*b+1] + az * P[3*b+2])
        : (nodes[b].x - ax) ** 2 + (nodes[b].y - ay) ** 2;
      if (d2 >= bestD[FIT_K - 1]) continue;
      let p = FIT_K - 1;
      while (p > 0 && bestD[p - 1] > d2) { bestD[p] = bestD[p - 1]; bestI[p] = bestI[p - 1]; p--; }
      bestD[p] = d2; bestI[p] = b;
    }
    let summe = 0, zahl = 0;
    for (let k = 0; k < FIT_K; k++) {
      const b = bestI[k];
      if (b < 0) continue;
      summe += aehnlich(a, b); zahl++;
    }
    raus[a] = zahl ? 1 - summe / zahl : 0;
  }
  return raus;
}

// Perzentil statt Rohwert: die Werte liegen eng beieinander, so nutzt die Skala aus.
function fremdAnteil(i) {
  if (!fremd) fremdheitRechnen();
  const v = fremd[i];
  let lo = 0, hi = fremdRang.length;
  while (lo < hi) { const m = (lo + hi) >> 1; if (fremdRang[m] < v) lo = m + 1; else hi = m; }
  return lo / fremdRang.length;
}

// Baut Knoten, Kanten, Momentum-Daten und die Simulation aus dem aktuellen Datensatz G.
// Wird initial und bei jedem Wechsel der Projektion aufgerufen.
function buildGraph() {
  if (sim) sim.stop();
  lageLauf++; lageOffen = false;   // eine noch laufende Anfrage gilt dem alten Aufbau
  signatur = baueSignatur();
  nodes = G.nodes.map((d, i) => ({ ...d, i, weg: d.slot ? !slotDaten.has(i) : wegListe.has(d.id.toLowerCase()),
    r: knotenRadius(d), r3: kugelRadius(d.m ?? d.n),
    x: d.ux, y: d.uy }));
  // Die Kugel-Lage ist ein eigenes Paket (`teil("kugel")`): angeboten, wenn der Bau sie
  // mitgibt, als P erst, wenn sie geladen ist.
  hatKugel = nodes.length > 0 && (!!(G.teile && G.teile.kugel) || Array.isArray(G.nodes[0].xyz));
  if (!hatKugel && projektion === "kugel") projektion = "flach";
  document.body.dataset.proj = projektion;
  if (Array.isArray(G.nodes[0].xyz)) {
    P = new Float64Array(nodes.length * 3);
    for (let i = 0; i < nodes.length; i++) {
      const q = G.nodes[i].xyz;
      P[3*i] = q[0]; P[3*i+1] = q[1]; P[3*i+2] = q[2];
    }
    SX = new Float32Array(nodes.length);
    SY = new Float32Array(nodes.length);
    SZ = new Float32Array(nodes.length);
  } else { P = null; }
  links = G.links.filter(l => !nodes[l.s].weg && !nodes[l.t].weg).map(l => ({ source: l.s, target: l.t, w: l.w }));
  kantenGewichte(links);
  nachbarn = nodes.map(() => new Set());
  links.forEach(l => { nachbarn[l.source].add(l.target); nachbarn[l.target].add(l.source); });
  labelFolge = nodes.slice().sort((a, b) => b.n - a.n);
  vektorenAnwenden();
  streuRangNeu();
  // aus der Suche Eingefügtes bekommt seine Kanten zurück, bevor die Simulation entsteht
  for (const i of slotDaten.keys()) {
    for (const l of kantenAnlegen(nodes[i], nodes.filter(x => !x.weg && x.i !== i))) {
      nachbarn[l.source].add(l.target); nachbarn[l.target].add(l.source);
    }
  }

  momentumAnwenden();
  hover = null; auswahl = null; aktivFuer = -1; panel.style.display = "none";
  themaFokus = null; themaSet = null;   // Indizes gelten nur für den alten Datensatz
  baueClusterLegende();

  // Nur sichtbare Knoten simulieren; die Kanten lösen darum über den Index im Datensatz auf
  sim = layoutSimulation(nodes.filter(d => !d.weg), links, repulsion)
    .on("tick", () => { if (!benutzerAktiv) einpassen(); render(); })
    .on("end", () => {
      if (!benutzerAktiv) einpassen();
      const xy = lageXY();
      layoutSichern(xy);
      layoutTeilen(xy);
      // Das Layout steht erst jetzt fest — die Nachbarschaften davor wären falsch.
      layoutFertig = true; fremd = null;
      if (modus === "fremd") { farbenAktualisieren(); render(); }
    });

  // Auf der Kugel gibt es kein Layout, das erst einschwingen müsste: Die Lage kommt
  // fertig aus dem Kartenbau. Die Simulation wird trotzdem angelegt — forceLink ersetzt
  // dabei die Kanten-Indizes durch Knotenobjekte, worauf beide Zeichner sich verlassen.
  if (projektion === "kugel") {
    sim.alpha(0);
    layoutFertig = true;
    baueBoegen();
    kantenBuendeln();
    farbenAktualisieren();
    render();
    letzteGeste = 0;
    anstossen();
    return;
  }

  kantenBuendeln();
  farbenAktualisieren();
  layoutFertig = false;
  layoutBesorgen(true);
}

/* ---------- Zeichnen ---------- */

// Alle Zeichnungen laufen über einen requestAnimationFrame-Scheduler: viele Events in
// einem Frame (mousemove, Zoom/Pan, Simulations-Ticks) lösen so nur EIN Redraw aus.
function render() {
  if (redrawGeplant) return;
  redrawGeplant = true;
  requestAnimationFrame(() => { redrawGeplant = false; draw(); });
}

// Kanten nach Deckkraft in Stufen bündeln: ein stroke() je Stufe statt eines je Kante
// (4385 Kanten → 8 Zeichenbefehle). Die Deckkraft hängt nur vom Gewicht ab, wird also
// einmal beim Aufbau bestimmt.
const KANTEN_STUFEN = 8;
let kantenGruppen = [];
function kantenBuendeln() {
  const basis = Math.min(0.7, 1730 / Math.max(1, links.length));
  const eimer = new Map();
  for (const l of links) {
    if (l.source.weg || l.target.weg) continue;   // gerade ausgeschlossen
    const a = G.mix ? l.z : Math.max(0, (l.w - 0.55) / 0.45);
    const stufe = Math.min(KANTEN_STUFEN - 1, Math.round(Math.min(1, a * a) * (KANTEN_STUFEN - 1)));
    let arr = eimer.get(stufe);
    if (!arr) eimer.set(stufe, arr = []);
    arr.push(l);
  }
  kantenGruppen = [...eimer].map(([stufe, l]) => ({
    // stärkere Kanten deckender und breiter: 0,6 bis 3 px
    a: Math.max(0.03, stufe / (KANTEN_STUFEN - 1) * basis), b: 0.6 + 2.4 * stufe / (KANTEN_STUFEN - 1), l,
  }));
}

// Knotenfarben ändern sich außerhalb des Momentum-Modus nicht je Frame → einmal berechnen
// und nach Farbe gruppieren, dann ein fill() je Farbe statt eines je Knoten.
let farbGruppen = new Map();
const momGruppen = new Map();
// Farbe je Knoten als flache Liste — die Kugel bündelt je Bild neu (die Tiefenstufe ändert
// sich beim Drehen) und würde `farbe()` sonst 1860-mal pro Bild auswerten. Bei "Source"
// steckt darin eine HSV-Mischung über alle Quellenanteile plus ein d3.hsl-Aufruf.
// Momentum bleibt außen vor: dort hängt die Farbe an der Woche, nicht am Knoten.
let farbeJeKnoten = [];
function farbenAktualisieren() {
  farbGruppen = new Map();
  farbeJeKnoten = modus === "momentum" ? [] : nodes.map(d => farbe(d));
  if (modus === "momentum") return;
  for (const d of nodes) {
    if (d.weg) continue;
    const f = farbe(d);
    let arr = farbGruppen.get(f);
    if (!arr) farbGruppen.set(f, arr = []);
    arr.push(d);
  }
}
function knotenGruppen() {
  if (modus !== "momentum") return farbGruppen;
  for (const arr of momGruppen.values()) arr.length = 0;
  for (const d of nodes) {
    if (d.weg) continue;
    const f = fremdesThema(d) ? THEMA_GRAU : MOM_LUT[(mom(d) * 255) | 0];
    let arr = momGruppen.get(f);
    if (!arr) momGruppen.set(f, arr = []);
    arr.push(d);
  }
  return momGruppen;
}

// Momentum-Glow: je Farbstufe einmal ein Sprite mit Radialverlauf rendern und danach nur
// noch skaliert kopieren. createRadialGradient je Knoten und Frame war der teuerste Teil
// des Zeitraffers; die Deckkraft steuert globalAlpha.
const GLOW_STUFEN = 16, GLOW_PX = 128;
const glowSprites = new Array(GLOW_STUFEN);
function glowSprite(stufe) {
  if (glowSprites[stufe]) return glowSprites[stufe];
  const s = document.createElement("canvas");
  s.width = s.height = GLOW_PX;
  const g = s.getContext("2d");
  const c = d3.color(MOM_LUT[Math.round(stufe / (GLOW_STUFEN - 1) * 255)]);
  const grad = g.createRadialGradient(GLOW_PX / 2, GLOW_PX / 2, 0, GLOW_PX / 2, GLOW_PX / 2, GLOW_PX / 2);
  c.opacity = 1; grad.addColorStop(0, c + "");
  c.opacity = 0; grad.addColorStop(1, c + "");
  g.fillStyle = grad;
  g.fillRect(0, 0, GLOW_PX, GLOW_PX);
  return glowSprites[stufe] = s;
}

// Sichtfenster in Weltkoordinaten, großzügig gepolstert — außerhalb liegende Knoten und
// Kanten spart der Zeichner ein (spürbar, sobald man hineinzoomt).
let vx0 = 0, vx1 = 0, vy0 = 0, vy1 = 0;
function sichtfenster() {
  const k = transform.k, rand = 60 / k;
  vx0 = -transform.x / k - rand; vx1 = (W - transform.x) / k + rand;
  vy0 = -transform.y / k - rand; vy1 = (H - transform.y) / k + rand;
}

let aktivSet = null, aktivFuer = -1;
function aktiveMenge(fokus) {
  if (!fokus) return null;
  if (aktivFuer !== fokus.i) {
    aktivFuer = fokus.i;
    aktivSet = new Set([fokus.i, ...nachbarn[fokus.i]]);
  }
  return aktivSet;
}

function draw() {
  if (projektion === "kugel") { zeichne3d(); return; }
  draw2d();
}

function draw2d() {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = T.bg;
  ctx.fillRect(0, 0, W, H);
  if (!W || !nodes.length || lageOffen) { ctx.globalAlpha = 1; return; }
  sichtfenster();
  // Nachbarschaft hervorheben nur nach Klick (auswahl); die Maus darüber bekommt bloß
  // den Ring und den Tooltip — sonst blendet jede Bewegung die ganze Karte aus.
  const ring = hover ?? auswahl;
  const aktiv = aktiveMenge(auswahl);
  ctx.translate(transform.x, transform.y);
  ctx.scale(transform.k, transform.k);

  zeichneKanten(aktiv);
  if (modus === "momentum") zeichneGlow(aktiv);
  zeichneKnoten(aktiv, ring);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  zeichneLabels(aktiv);
  ctx.globalAlpha = 1;
}

function zeichneKanten(aktiv) {
  ctx.globalCompositeOperation = T.kantenModus;
  ctx.strokeStyle = T.kante;
  const dim = aktiv ? 0.06 : themaSet ? 0.22 : 1;
  for (const g of kantenGruppen) {
    ctx.globalAlpha = g.a * dim * T.kantenFaktor;
    ctx.lineWidth = g.b / transform.k;
    ctx.beginPath();
    for (const l of g.l) {
      const s = l.source, t = l.target;
      if ((s.x < vx0 && t.x < vx0) || (s.x > vx1 && t.x > vx1) ||
          (s.y < vy0 && t.y < vy0) || (s.y > vy1 && t.y > vy1)) continue;
      ctx.moveTo(s.x, s.y); ctx.lineTo(t.x, t.y);
    }
    ctx.stroke();
  }
  const hell = aktiv ?? themaSet;  // Kanten innerhalb des Fokus voll deckend darüber
  if (hell) {
    for (const g of kantenGruppen) {
      let offen = false;
      for (const l of g.l) {
        if (!hell.has(l.source.i) || !hell.has(l.target.i)) continue;
        if (!offen) { ctx.globalAlpha = g.a; ctx.lineWidth = g.b / transform.k; ctx.beginPath(); offen = true; }
        ctx.moveTo(l.source.x, l.source.y); ctx.lineTo(l.target.x, l.target.y);
      }
      if (offen) ctx.stroke();
    }
  }
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = 1;
}

function zeichneGlow(aktiv) {
  ctx.globalCompositeOperation = T.glowModus;
  for (const d of nodes) {
    const m = mom(d);
    if (d.weg || m < 0.06 || (aktiv && !aktiv.has(d.i)) || fremdesThema(d)) continue;
    const gr = radius(d) * (2.4 + 3.2 * m);
    if (d.x + gr < vx0 || d.x - gr > vx1 || d.y + gr < vy0 || d.y - gr > vy1) continue;
    const puls = spielend ? 0.82 + 0.18 * Math.sin(animPhase * 4 + d.i) : 1;
    ctx.globalAlpha = 0.55 * m * puls;
    ctx.drawImage(glowSprite(Math.round(m * (GLOW_STUFEN - 1))), d.x - gr, d.y - gr, gr * 2, gr * 2);
  }
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = 1;
}

function zeichneKnoten(aktiv, fokus) {
  const grund = aktiv ? 0.07 : 0.92;
  ctx.globalAlpha = grund;
  for (const [f, liste] of knotenGruppen()) {
    if (!liste.length) continue;
    ctx.globalAlpha = themaSet && f === THEMA_GRAU ? grund * 0.55 : grund;
    ctx.fillStyle = f;
    ctx.beginPath();
    for (const d of liste) {
      const r = radius(d);
      if (d.x + r < vx0 || d.x - r > vx1 || d.y + r < vy0 || d.y - r > vy1) continue;
      ctx.moveTo(d.x + r, d.y);
      ctx.arc(d.x, d.y, r, 0, TAU);
    }
    ctx.fill();
  }
  if (aktiv) {                     // hervorgehobene Knoten voll deckend darüber
    ctx.globalAlpha = 0.92;
    for (const i of aktiv) {
      const d = nodes[i];
      ctx.fillStyle = farbe(d);
      ctx.beginPath();
      ctx.arc(d.x, d.y, radius(d), 0, TAU);
      ctx.fill();
    }
  }
  if (fokus) {
    ctx.globalAlpha = 1;
    ctx.lineWidth = 1.6 / transform.k;
    ctx.strokeStyle = T.fokusRing;
    ctx.beginPath();
    ctx.arc(fokus.x, fokus.y, radius(fokus), 0, TAU);
    ctx.stroke();
  }
}

// Labels im Bildschirmraum: schärfere Schrift, und die Kollisionsprüfung rechnet in
// denselben Einheiten (vorher wurden Bildschirmabstände nochmals mit k skaliert —
// herausgezoomt verschwanden Labels grundlos, hineingezoomt überlappten sie).
// Verglichen werden die Label-Rechtecke exakt; das Raster ist nur ein Index auf die
// Nachbarschaft. Vorher galt eine ganze Rasterzelle als belegt — weil das Raster
// bildschirmfest ist, die Labels beim Ziehen aber wandern, kippte die Entscheidung bei
// jedem Zellenübertritt und einzelne Labels flackerten. Rechteck gegen Rechteck ist
// gegenüber dem Verschieben invariant: alle Labels wandern um denselben Betrag.
const ZELLE = 48;
const zellen = new Map();   // Zellindex -> flache Liste [x0,y0,x1,y1, …]
function platzNehmen(x0, y0, x1, y1) {
  const c0 = Math.floor(x0 / ZELLE), c1 = Math.floor(x1 / ZELLE);
  const r0 = Math.floor(y0 / ZELLE), r1 = Math.floor(y1 / ZELLE);
  for (let r = r0; r <= r1; r++) {
    for (let c = c0; c <= c1; c++) {
      const rechtecke = zellen.get(r * 1048576 + c);
      if (!rechtecke) continue;
      for (let i = 0; i < rechtecke.length; i += 4) {
        if (x0 < rechtecke[i + 2] && x1 > rechtecke[i] &&
            y0 < rechtecke[i + 3] && y1 > rechtecke[i + 1]) return false;
      }
    }
  }
  for (let r = r0; r <= r1; r++) {
    for (let c = c0; c <= c1; c++) {
      const schluessel = r * 1048576 + c;
      let rechtecke = zellen.get(schluessel);
      if (!rechtecke) zellen.set(schluessel, rechtecke = []);
      rechtecke.push(x0, y0, x1, y1);
    }
  }
  return true;
}

const fontCache = new Map();
function schrift(fs) {
  let f = fontCache.get(fs);
  if (!f) fontCache.set(fs, f = `500 ${fs}px -apple-system, sans-serif`);
  return f;
}
// Textbreite einmal je Keyword bei Referenzgröße messen und linear skalieren: die alte
// Schätzung (Zeichenzahl × 0,31) verfehlte breite Glyphen deutlich — bei exakter
// Rechteckprüfung schlägt sich das direkt in überlappenden oder zu früh verworfenen
// Labels nieder.
const MESS_PX = 20;
const breiteJeZeichen = new Map();
function halbeBreite(id, fs) {
  let w = breiteJeZeichen.get(id);
  if (w === undefined) {
    ctx.font = schrift(MESS_PX);
    breiteJeZeichen.set(id, w = ctx.measureText(id).width / MESS_PX);
  }
  return w * fs / 2;
}

// Die Platzvergabe läuft über ALLE Labels, auch die außerhalb des Bildes: verdeckt ein
// Label knapp neben dem Rand ein sichtbares, muss das beim Verschieben so bleiben. Mit
// Sichtfenster-Filter rutschen beim Ziehen laufend neue Kandidaten in die Vergabe und
// stoßen sichtbare Labels heraus — gemessen bis zu 4 Wechsel je 20 px, obwohl die
// Rechteckprüfung selbst verschiebungsinvariant ist (ohne Filter: null Wechsel; Kosten
// bei 1000 Knoten 0,3–0,7 ms je Frame). Gezeichnet wird nur, was im Bild liegt.
function zeichneLabels(aktiv) {
  ctx.globalAlpha = 1;
  ctx.textAlign = "center";
  zellen.clear();
  const k = transform.k;
  for (const d of labelFolge) {
    // Im Themen-Fokus nur die Labels des Themas: das ist die lauteste Ebene. Der frei
    // werdende Platz geht an die Knoten, um die es geht — darum dort auch die kleineren.
    if (d.weg || (aktiv ? !aktiv.has(d.i) : d.r * k <= (themaSet ? 3.5 : LABEL_AB))) continue;
    if (!aktiv && themaSet && !themaSet.has(d.i)) continue;
    const px = transform.applyX(d.x), py = transform.applyY(d.y) - d.r * k - 4;
    if (!(Math.abs(px) < 1e6 && Math.abs(py) < 1e6)) continue;   // Zellindex im sicheren Bereich
    const fs = Math.round(Math.min(15, Math.max(10.5, d.r * k * 0.55)) * 2) / 2;
    const halb = halbeBreite(d.id, fs) + 3;
    if (!platzNehmen(px - halb, py - fs, px + halb, py + 4)) continue;
    if (px + halb < 0 || px - halb > W || py + 4 < 0 || py - fs > H) continue;
    ctx.font = schrift(fs);
    ctx.fillStyle = T.labelHalo;
    ctx.fillText(d.id, px, py + 1);
    ctx.fillStyle = aktiv ? T.labelText : T.labelDim;
    ctx.fillText(d.id, px, py);
  }
}

/* ---------- Interaktion ---------- */

function knotenBei(px, py) {
  if (projektion === "kugel") return knotenBei3d(px, py);
  const [x, y] = transform.invert([px, py]);
  let best = null, bd = 12 / transform.k + 4;
  for (const d of nodes) {
    if (d.weg) continue;
    const dist = Math.hypot(d.x - x, d.y - y);
    if (dist < bd + d.r) { best = d; bd = dist; }
  }
  return best;
}

canvas.addEventListener("mousemove", e => {
  if (zieht) return;              // beim Drehen flackerte der Tooltip sonst durch
  const treffer = knotenBei(e.clientX, e.clientY);
  if (treffer) {
    tip.style.display = "block";
    tip.style.left = Math.max(8, Math.min(e.clientX + 14, W - 280)) + "px";
    tip.style.top = e.clientY + 14 + "px";
    if (treffer !== hover) {
      tip.innerHTML = `<b>${esc(treffer.id)}</b><br><small>${treffer.n} articles${
        treffer.like != null ? ` · ${Math.round(treffer.like * 100)} % liked (${treffer.nb} rated)` : ""}</small>`;
    }
  } else if (hover) tip.style.display = "none";
  if (treffer === hover) return;   // nur bei echtem Wechsel neu zeichnen
  hover = treffer;
  canvas.style.cursor = hover ? "pointer" : "grab";
  render();
});
canvas.addEventListener("mouseleave", () => {
  if (!hover) return;
  hover = null; tip.style.display = "none"; render();
});

// Nach einem Zieh-Vorgang darf der abschließende Klick keinen Knoten auswählen.
let druckPunkt = null;
canvas.addEventListener("pointerdown", e => { druckPunkt = [e.clientX, e.clientY]; });
canvas.addEventListener("click", e => {
  if (druckPunkt && Math.hypot(e.clientX - druckPunkt[0], e.clientY - druckPunkt[1]) > 5) return;
  auswahl = knotenBei(e.clientX, e.clientY);
  // Auf der Kugel den getroffenen Knoten in die Mitte drehen — am Rand steht er sonst
  // stark verkürzt und seine Nachbarschaft ist gar nicht zu sehen.
  if (projektion === "kugel" && auswahl) drehZu(auswahl);
  zeigePanel();
});

/* ---------- Kugel: Drehen und Zoomen ----------
   Die Ebene hängt an d3.zoom, die Kugel an eigenen Zeiger-Ereignissen. Beide gleichzeitig
   gebunden zu lassen ginge nicht: d3.zoom schluckt Rad und Ziehen, bevor die Drehung sie
   sieht. `bindeEingabe` schaltet darum je Projektion um. */
const zeiger = new Map();
let pinch0 = 0, r0Pinch = 0;

function bindeEingabe() {
  if (projektion === "kugel") zoomSel.on(".zoom", null);
  else zoomSel.call(zoom);
}

canvas.addEventListener("pointerdown", e => {
  if (projektion !== "kugel") return;
  zeiger.set(e.pointerId, [e.clientX, e.clientY]);
  if (zeiger.size === 1) {
    zieht = true; vlam = vphi = 0; flug = null;
    try { canvas.setPointerCapture(e.pointerId); } catch { /* synthetische Ereignisse */ }
    anstossen();
  } else if (zeiger.size === 2) {
    const [a, b] = [...zeiger.values()];
    pinch0 = Math.hypot(a[0] - b[0], a[1] - b[1]); r0Pinch = R;
  }
});
canvas.addEventListener("pointermove", e => {
  if (projektion !== "kugel") return;
  const vorher = zeiger.get(e.pointerId);
  if (!vorher) return;
  const dx = e.clientX - vorher[0], dy = e.clientY - vorher[1];
  zeiger.set(e.pointerId, [e.clientX, e.clientY]);
  letzteGeste = performance.now();
  if (zeiger.size >= 2) {
    const [a, b] = [...zeiger.values()];
    const d = Math.hypot(a[0] - b[0], a[1] - b[1]);
    if (pinch0 > 10) setzeRadius(r0Pinch * d / pinch0);
    render();
    return;
  }
  // Ein Bildpunkt Zug soll den Punkt unter dem Finger um einen Bildpunkt mitnehmen, also
  // um 1/R Bogenmaß. Der Kosinus korrigiert die Längsdrehung nahe den Polen: dort legt ein
  // Längengrad weniger Weg zurück, ohne ihn klebte der Zeiger nicht mehr am Punkt.
  // Beim Nicken wird dy NICHT negiert — die Projektion spiegelt y bereits (wie globe.js).
  vlam = -dx / (R * Math.max(0.25, Math.cos(phi)));
  vphi = dy / R;
  lam += vlam;
  phi = klemm(phi + vphi, -1.45, 1.45);
  anstossen();
});
function zeigerEnde(e) {
  if (!zeiger.has(e.pointerId)) return;
  zeiger.delete(e.pointerId);
  if (zeiger.size === 0) { zieht = false; letzteGeste = performance.now(); anstossen(); }
}
canvas.addEventListener("pointerup", zeigerEnde);
canvas.addEventListener("pointercancel", zeigerEnde);
canvas.addEventListener("wheel", e => {
  if (projektion !== "kugel") return;
  e.preventDefault();
  setzeRadius(R * Math.exp(-e.deltaY * 0.0016));
  letzteGeste = performance.now();
  render();
}, { passive: false });

/* "Was liegt eigentlich drumherum?" muss man nicht raten: Hier steht, wie sich die zwölf
   räumlich nächsten Knoten auf Themen verteilen. Bewusst die räumlichen Nachbarn und
   nicht die Kanten — es ist die Antwort auf das, was man beim Draufschauen sieht. Zwölf
   statt sechs, damit die Verteilung nicht schon an einem Ausreißer kippt. */
const UMGEBUNG_K = 12;
function umgebungText(d) {
  const sicht = nodes.filter(n => !n.weg);
  const K = Math.min(UMGEBUNG_K, sicht.length - 1);
  if (K < 3) return "";
  const kugel = projektion === "kugel" && P;
  const naeher = (a, b) => a > b;      // Skalarprodukt: größer = näher
  const bd = new Float64Array(K).fill(-Infinity), bi = new Int32Array(K).fill(-1);
  for (const n of sicht) {
    if (n.i === d.i) continue;
    const w = kugel
      ? P[3*d.i]*P[3*n.i] + P[3*d.i+1]*P[3*n.i+1] + P[3*d.i+2]*P[3*n.i+2]
      : -Math.hypot(n.x - d.x, n.y - d.y);   // negierter Abstand, damit größer = näher
    if (!naeher(w, bd[K-1])) continue;
    let k = K - 1;
    while (k > 0 && naeher(w, bd[k-1])) { bd[k] = bd[k-1]; bi[k] = bi[k-1]; k--; }
    bd[k] = w; bi[k] = n.i;
  }
  const zaehl = new Map();
  for (let k = 0; k < K; k++) {
    if (bi[k] < 0) continue;
    const c = nodes[bi[k]].cluster;
    zaehl.set(c, (zaehl.get(c) || 0) + 1);
  }
  const sortiert = [...zaehl].sort((x, y) => y[1] - x[1]);
  if (!sortiert.length) return "";
  const balken = sortiert.map(([c, z]) =>
    `<span class="umg" style="--f:${themenFarbe(c)};--b:${z / K * 100}%">`
    + `${esc(c < 0 ? "No topic" : G.cluster[c])} <i>${z}</i></span>`).join("");
  return `<h3>Surroundings</h3><div class="umgebung">${balken}</div>`;
}

const artikelHtml = art => art.map(a =>
  `<a href="${sicherUrl(a.u)}" target="_blank" rel="noopener">${esc(a.t)}</a>`).join("");
function zeigePanel() {
  if (!auswahl) { panel.style.display = "none"; render(); return; }
  const d = auswahl;
  if (!teilDa.has("details") && G.teile && G.teile.details)
    teil("details").then(() => { if (auswahl === d) zeigePanel(); }, () => {});
  const naechste = links
    .filter(l => l.source.i === d.i || l.target.i === d.i)
    .sort((a, b) => b.w - a.w)
    .map(l => l.source.i === d.i ? l.target : l.source)
    .filter(n => !n.weg).slice(0, 6);
  // Die Artikel je Zeitraum fragt der Momentum-Modus beim Server an; die Demo zeigt dort
  // die typischen Artikel.
  const zeitraum = modus === "momentum" && !DEMO;
  panel.innerHTML = `
    <button class="zu">✕</button>
    <h2>${esc(d.id)}</h2>
    <div class="meta">${d.n} articles${d.nb ? ` · ${d.nb} rated` : ""}<br>Topic: ${
      d.cluster < 0 ? "none" : esc(G.cluster[d.cluster])}${
      d.spread === undefined ? "" : `<br>Time spread: ${Math.round(d.spread * 100)} %`}${
      d.focus === undefined ? "" : ` · Focus: ${String(d.focus).replace(".", ",")}`}${
      d.streu == null ? "" : `<br>Topic spread: ${String(d.streu).replace(".", ",")} · broader than ${
        Math.round(streuRang(d.streu) * 100)} % of the map`}${sucheZeile(d)}</div>
    ${d.like != null ? `<div style="font-size:12.5px;color:#8b93ad">Like rate: <b style="color:${likeSkala(d.like)}">${Math.round(d.like * 100)} %</b></div>
    <div class="balken"><div style="width:${d.like * 100}%;background:${likeSkala(d.like)}"></div></div>` : ""}
    ${zeitraum
      ? `<h3>Articles in period</h3><div class="zr-info"></div><div class="zr-liste"></div>`
      : `<h3>Typical articles</h3><div class="typisch">${
          d.art ? artikelHtml(d.art) : `<div class="zr-leer">loading …</div>`}</div>`}
    ${umgebungText(d)}
    <h3>Nearest keywords</h3>
    ${naechste.map(n => `<span class="nachbar" data-i="${n.i}">${esc(n.id)}</span>`).join("")}
    <div class="aus"><button class="start">Exclude keyword</button></div>`;
  panel.style.display = "block";
  panel.querySelector(".zu").onclick = () => { auswahl = null; zeigePanel(); };
  panel.querySelectorAll(".nachbar").forEach(el =>
    el.onclick = () => { auswahl = nodes[+el.dataset.i]; springeZu(auswahl); zeigePanel(); });
  ausschlussKnopf(panel.querySelector(".aus"), d);
  if (zeitraum) ladeZeitraum();
  else if (!d.art) {
    const fuellen = html => { const box = auswahl === d && panel.querySelector(".typisch"); if (box) box.innerHTML = html; };
    artikelLaden(d).then(art => fuellen(artikelHtml(art)),
                         () => fuellen(`<div class="zr-leer">Couldn't load articles.</div>`));
  }
  render();
}

// Ausschließen ist absichtlich zweistufig: ein Fehltipper auf dem Handy würde sonst
// still ein Keyword von der Karte nehmen, und rückgängig macht man das nur am Mac.
function ausschlussKnopf(box, d) {
  box.querySelector(".start").onclick = () => {
    box.innerHTML = `<div class="frage">Really exclude “${esc(d.id)}” from the map?</div>
      <div class="knoepfe"><button class="nein">Cancel</button><button class="ja">Exclude</button></div>`;
    box.querySelector(".nein").onclick = () => {
      box.innerHTML = `<button class="start">Exclude keyword</button>`;
      ausschlussKnopf(box, d);
    };
    box.querySelector(".ja").onclick = async () => {
      const ja = box.querySelector(".ja");
      ja.disabled = true; ja.textContent = "…";
      try {
        const r = await fetch("api/excluded_keywords", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ keyword: d.id }),
        });
        if (!r.ok) throw new Error(String(r.status));
      } catch {
        box.innerHTML = `<div class="frage fehler">Couldn't save the exclusion.</div>
          <div class="knoepfe"><button class="start">Try again</button></div>`;
        ausschlussKnopf(box, d);
        return;
      }
      verstecke(d);
      auswahl = null; zeigePanel();
      ladeBauStand();   // Statuszeile im Settings-Panel zieht nach
    };
  };
}

// Der Knoten verschwindet sofort aus der Ansicht; aus den Daten fällt er erst beim
// nächsten `news build-map`. Gemerkt wird der casefold-Name, nicht das Objekt — beim
// Wechsel der Quellen-Gewichtung baut buildGraph() neue Knoten.
const wegListe = new Set();
function verstecke(d) {
  wegListe.add(d.id.toLowerCase());
  d.weg = true;
  if (hover === d) { hover = null; tip.style.display = "none"; }
  kantenBuendeln();
  farbenAktualisieren();
  render();
}

function fensterDaten(w) {
  const s = Math.max(0, w - (WIN - 1));
  return [new Date(startMs + s * MS_WEEK), new Date(startMs + (w + 1) * MS_WEEK)];
}
const isoTag = dt => dt.toISOString().slice(0, 10);
const fmtTag = dt => String(dt.getUTCDate()).padStart(2, "0") + "." +
  String(dt.getUTCMonth() + 1).padStart(2, "0") + ".";

let zrTimer = null;
function planeZeitraum() {
  if (modus !== "momentum" || !auswahl || spielend) return;
  clearTimeout(zrTimer);
  zrTimer = setTimeout(ladeZeitraum, 220);
}
async function ladeZeitraum() {
  if (modus !== "momentum" || !auswahl) return;
  const liste = panel.querySelector(".zr-liste");
  if (!liste) return;
  const w = Math.round(pos), [a, b] = fensterDaten(w);
  const info = panel.querySelector(".zr-info");
  if (info) info.textContent = `${fmtTag(a)} – ${fmtTag(new Date(b - 86400000))} · ${WIN} weeks`;
  const schluessel = auswahl.id + "|" + w;
  if (liste.dataset.key === schluessel) return;   // schon geladen
  liste.dataset.key = schluessel;
  if (!liste.childElementCount) liste.innerHTML = `<div class="zr-leer">loading …</div>`;
  try {
    const r = await fetch(`api/keyword_articles?keyword=${encodeURIComponent(auswahl.id)}`
      + `&start=${isoTag(a)}&end=${isoTag(b)}`);
    const j = await r.json();
    if (liste.dataset.key !== schluessel) return;   // veraltet, neuere Anfrage läuft
    liste.innerHTML = j.articles.length
      ? j.articles.map(x => `<a href="${sicherUrl(x.url)}" target="_blank" rel="noopener">${esc(x.title)}</a>`).join("")
      : `<div class="zr-leer">No articles in this period.</div>`;
  } catch {
    liste.dataset.key = "";
    liste.innerHTML = `<div class="zr-leer">Couldn't load articles.</div>`;
  }
}

/* ---------- Zeitleiste ---------- */

const WOCHEN_PRO_SEK = 6;
function zeigeWoche() {
  const w = Math.round(pos);
  slider.value = w;
  wochenlabel.textContent = wochen[w] || "";
  render();
  planeZeitraum();
}
slider.addEventListener("input", () => { stopPlay(); pos = +slider.value; zeigeWoche(); });

let lastTs = 0;
function schritt(ts) {
  if (!spielend) return;
  const dt = lastTs ? Math.min(0.05, (ts - lastTs) / 1000) : 0;
  lastTs = ts;
  animPhase += dt;
  pos = Math.min(NW - 1, pos + dt * WOCHEN_PRO_SEK);
  zeigeWoche();
  if (pos >= NW - 1) { stopPlay(); return; }
  requestAnimationFrame(schritt);
}
function startPlay() {
  if (NW < 2) return;
  if (pos >= NW - 1) pos = 0;
  spielend = true; lastTs = 0; playBtn.textContent = "⏸";
  requestAnimationFrame(schritt);
}
function stopPlay() {
  if (!spielend) return;
  spielend = false; playBtn.textContent = "▶";
  render();          // Puls-Faktor zurück auf 1
  planeZeitraum();   // Artikel für die stehengebliebene Woche nachladen
}
playBtn.onclick = () => spielend ? stopPlay() : startPlay();

// Jahres-Ticks unter dem Slider (je Datensatz neu aufgebaut)
function baueTicks() {
  const ticksEl = document.getElementById("ticks");
  ticksEl.textContent = "";
  let letztesJahr = "";
  wochen.forEach((label, w) => {
    const jahr = label.slice(-4);
    if (!jahr || jahr === letztesJahr) return;
    letztesJahr = jahr;
    const t = document.createElement("span");
    t.textContent = jahr;
    t.style.left = (w / Math.max(NW - 1, 1) * 100) + "%";
    ticksEl.appendChild(t);
  });
}

/* ---------- Modi, Legenden, Einstellungen ---------- */

const MODUS_TEILE = { similar: ["details"], fremd: ["vektoren"], streuung: ["details"],
                      like: ["details"], momentum: ["momentum"], quelle: ["details"] };
let modusLauf = 0;
document.querySelectorAll("#ui button[data-m]").forEach(b => b.onclick = async () => {
  const ab = modus === b.dataset.m;   // zweiter Tipp auf den aktiven Modus: keine Einfärbung
  const neu = ab ? "keine" : b.dataset.m, lauf = ++modusLauf;
  try { await Promise.all((MODUS_TEILE[neu] || []).map(teil)); }
  catch { if (lauf === modusLauf) legende.textContent = "Couldn't load the data for this mode."; return; }
  if (lauf !== modusLauf) return;   // inzwischen ein anderer Modus gewählt
  document.querySelectorAll("#ui button[data-m]").forEach(x => x.classList.remove("aktiv"));
  if (!ab) b.classList.add("aktiv");
  modus = neu;
  farbenAktualisieren();
  legende.innerHTML = legendeText(modus);
  zeitleiste.classList.toggle("an", modus === "momentum");
  if (modus === "momentum") zeigeWoche(); else stopPlay();
  if (auswahl) zeigePanel();
  render();
});

// Cluster-Legende (je Datensatz neu aufgebaut, Auf-/Zuklapp-Zustand bleibt erhalten)
let clusterZu = innerWidth <= 720;
function baueClusterLegende() {
  const legendeEl = document.getElementById("cluster-legende");
  legendeEl.textContent = "";
  legendeEl.classList.toggle("zu", clusterZu);
  const kopf = document.createElement("div");
  kopf.id = "cluster-kopf";
  const kopfText = () => `${clusterZu ? "▸" : "▾"} Topics`;
  kopf.textContent = kopfText();
  kopf.onclick = () => {
    clusterZu = !clusterZu;
    legendeEl.classList.toggle("zu", clusterZu);
    kopf.textContent = kopfText();
    if (clusterZu && themaFokus !== null) setzeThemaFokus(null);   // sonst nicht mehr lösbar
  };
  legendeEl.appendChild(kopf);
  // Feste Themen: in Config-Reihenfolge, nicht nach Größe sortiert — die Legende soll von
  // Karte zu Karte an derselben Stelle stehen. Das Grau kommt nur dazu, wenn es vorkommt.
  const groesse = new Map();
  for (const d of nodes) if (!d.weg) groesse.set(d.cluster, (groesse.get(d.cluster) || 0) + 1);
  const eintraege = G.cluster.map((_, c) => c).filter(c => groesse.has(c));
  if (groesse.has(-1)) eintraege.push(-1);
  eintraege.forEach(c => {
      const el = document.createElement("div");
      el.className = "eintrag";
      const name = c < 0 ? "No topic" : G.cluster[c];
      el.innerHTML = `<span class="punkt" style="background:${themenFarbe(c)}"></span>`
        + `${esc(name)} <span class="zahl">${groesse.get(c)}</span>`;
      el.dataset.c = c;
      el.classList.toggle("aktiv", themaFokus === c);
      el.onclick = () => {
        const teil = nodes.filter(d => d.cluster === c && !d.weg);
        if (!teil.length) return;
        const neu = themaFokus === c ? null : c;   // zweiter Klick hebt den Fokus wieder auf
        setzeThemaFokus(neu);
        if (neu === null) return;
        if (projektion === "kugel") {
          // Schwerpunkt der Themenknoten auf der Kugel: Mittelvektor, wieder normiert.
          let mx = 0, my = 0, mz = 0;
          for (const d of teil) { mx += P[3*d.i]; my += P[3*d.i+1]; mz += P[3*d.i+2]; }
          const l = Math.hypot(mx, my, mz) || 1;
          flug = { t: 0, dauer: 0.7, l0: lam, p0: phi,
                   dl: ((Math.atan2(my, mx) - lam + Math.PI * 3) % TAU2) - Math.PI,
                   dp: klemm(Math.asin(klemm(mz / l, -1, 1)), -1.45, 1.45) - phi,
                   r0: R, dr: 0 };
          letzteGeste = performance.now();
          anstossen();
          return;
        }
        benutzerAktiv = true;
        const [x0, x1] = d3.extent(teil, d => d.x), [y0, y1] = d3.extent(teil, d => d.y);
        const k = Math.min(W / (x1 - x0 + 160), H / (y1 - y0 + 160), 4);
        const t = d3.zoomIdentity.translate(W / 2 - (x0 + x1) / 2 * k, H / 2 - (y0 + y1) / 2 * k).scale(k);
        zoomSel.transition().duration(700).call(zoom.transform, t);
      };
      legendeEl.appendChild(el);
  });
}

// Ein Thema hervorheben: alles andere wird grau. Gilt in jedem Farbmodus — auch in
// Similarity und Misfits ist die Frage „wo liegt dieses Thema" eine sinnvolle.
function setzeThemaFokus(c) {
  themaFokus = c;
  themaSet = c === null ? null : new Set(nodes.filter(d => d.cluster === c && !d.weg).map(d => d.i));
  document.querySelectorAll("#cluster-legende .eintrag").forEach(el =>
    el.classList.toggle("aktiv", +el.dataset.c === c));
  farbenAktualisieren();
  render();
}

// Settings: Quellen-Gewichtung (Datensatz-Wechsel) + Farbmischung (nur Frontend)
const settingsBtn = document.getElementById("settingsBtn");
const settingsPanel = document.getElementById("settings");
settingsBtn.onclick = () => {
  const offen = settingsPanel.classList.toggle("an");
  settingsBtn.classList.toggle("aktiv", offen);
  if (offen) ladeBauStand();   // Bau-Status beim Öffnen frisch holen statt zu pollen
};
function markiereSettings() {
  settingsPanel.querySelectorAll("[data-f]").forEach(b =>
    b.classList.toggle("aktiv", b.dataset.f === farbmix));
  settingsPanel.querySelectorAll("[data-p]").forEach(b => {
    b.classList.toggle("aktiv", b.dataset.p === projektion);
    b.disabled = b.dataset.p === "kugel" && !hatKugel;
  });
  settingsPanel.querySelectorAll("[data-d]").forEach(b =>
    b.classList.toggle("aktiv", b.dataset.d === (drift ? "an" : "aus")));
  rueckWert.textContent = Math.round(rueckseite * 100) + " %";
}

/* Projektion umschalten. Der Graph wird neu aufgebaut, weil sich daran auch hängt, ob
   das Kraft-Layout läuft — auf der Kugel steht die Lage fest. */
const rueckWert = document.getElementById("rueckWert");
async function setzeProjektion(p) {
  if (p === projektion || (p === "kugel" && !hatKugel)) { markiereSettings(); return; }
  if (p === "kugel") try { await teil("kugel"); } catch { markiereSettings(); return; }
  projektion = p;
  lsSet("map_projektion", p);
  document.body.dataset.proj = p;
  bindeEingabe();
  buildGraph();
  legende.innerHTML = legendeText(modus);
  markiereSettings();
}
settingsPanel.querySelectorAll("[data-p]").forEach(b =>
  b.onclick = () => setzeProjektion(b.dataset.p));
settingsPanel.querySelectorAll("[data-d]").forEach(b => b.onclick = () => {
  drift = b.dataset.d === "an";
  lsSet("map_drift", b.dataset.d);
  markiereSettings();
  letzteGeste = 0;
  anstossen();
});
const rueckSlider = document.getElementById("rueck");
rueckSlider.value = Math.round(rueckseite * 100);
rueckSlider.addEventListener("input", () => {
  rueckseite = +rueckSlider.value / 100;
  lsSet("map_rueck", rueckSlider.value);
  markiereSettings();
  render();
});
settingsPanel.querySelectorAll("[data-f]").forEach(b => b.onclick = () => {
  farbmix = b.dataset.f;
  lsSet("map_farbmix", farbmix);
  markiereSettings();
  farbenAktualisieren();
  if (modus === "quelle") legende.innerHTML = legendeText(modus);
  render();
});

// Abstoßungs-Regler: beim Loslassen die Lage für den neuen Wert besorgen — aus Gerät oder
// Datenbank, sonst von der UMAP-Startlage aus gerechnet. Vom aktuellen Stand aus aufgeheizt
// hing das Ergebnis am Weg des Reglers: 170 → 60 → 400 presste die Karte zur Scheibe, und
// zurück auf 170 blieb sie rund (Umriss-Unruhe 0,23 → 0,07), obwohl 400 vom Start aus so
// gegliedert ist wie 170 (0,22). Gespeichert wird je Wert, der Weg darf keine Rolle spielen.
const repSlider = document.getElementById("repulsion"), repWert = document.getElementById("repWert");
repSlider.value = repWert.textContent = repulsion;
repSlider.addEventListener("input", () => { repWert.textContent = repSlider.value; });
repSlider.addEventListener("change", () => {
  repulsion = +repSlider.value;
  lsSet("map_repulsion", repulsion);
  if (sim && projektion !== "kugel") layoutBesorgen(false);
});

// Die Bau-Einstellungen gelten geräteübergreifend: die Karte wird auf dem Mac vorberechnet,
// hier wird nur der Wunsch hinterlegt (meta.map_settings). Ob er schon gerechnet ist, sagt
// der Vergleich mit dem gebauten Stand (meta.map_built_settings); den Neubau stößt die
// Menüleisten-App an — automatisch, wenn dort die Automatik läuft.
const bauStatus = document.getElementById("bauStatus");
let bauStand = null;   // {desired, built, limits} — null, solange nichts geladen ist

const dezimal = n => Number(n).toLocaleString("de-DE");
function zeitpunkt(iso) {
  const t = new Date(iso);
  return isNaN(t) ? "" : t.toLocaleString("de-DE",
    { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
}
// Signaturen sind "Anzahl:Kurzhash" — die Anzahl ist auch die Anzeige, der Hash
// unterscheidet "eines raus, eines rein" von "unverändert".
const sigZahl = sig => +String(sig || "").split(":")[0] || 0;
function gebautText(b) {
  const wann = zeitpunkt(b.built_at);
  const raus = sigZahl(b.excluded);
  const filter = [
    b.time_spread ? `spread \u2265 ${b.time_spread} %` : null,
    b.ambiguity ? `\u2212${b.ambiguity} % ambiguous` : null,
  ].filter(Boolean).join(", ");
  const zusammen = sigZahl(b.groups);
  return `${dezimal(b.nodes_actual ?? b.nodes)} keywords · ${sigZahl(b.topics) || G.cluster.length} topics`
       + (b.edges ? ` · ${b.edges} edges/keyword` : "")
       + (b.mix ? ` · ${b.mix} % co-occurrence` : "")
       + (b.merge === false ? " · groups separate" : "")
       + (filter ? ` · ${filter}` : "") + (raus ? ` · ${raus} excluded` : "")
       + (zusammen ? ` · ${zusammen} merged` : "")
       + (wann ? ` · ${wann}` : "");
}
function zeigeBauStatus(text, offen) {
  bauStatus.textContent = text;
  bauStatus.classList.toggle("offen", !!offen);
}
/* Die Regler, die einen Kartenbau brauchen, und der Gruppen-Schalter. Alle nach demselben
   Muster: Der Wunsch liegt in meta.map_settings, gerechnet wird auf dem Mac, und die
   Differenz zu map_built_settings ist die "Pending"-Meldung. Kennt der Server einen Wert
   nicht, bleibt sein Regler gesperrt, statt einen Wunsch vorzugaukeln, den niemand
   entgegennimmt. */
const BAU_REGLER = [
  { id: "knoten", feld: "nodes", wert: "knotenWert", text: v => dezimal(v) },
  { id: "kanten", feld: "edges", wert: "kantenWert", text: v => v },
  { id: "zeit", feld: "time_spread", wert: "zeitWert", text: v => +v ? v + " %" : "off" },
  { id: "fokus", feld: "ambiguity", wert: "fokusWert", text: v => +v ? "\u2212" + v + " %" : "off" },
  { id: "mischung", feld: "mix", wert: "mischungWert", text: v => +v ? v + " % co-occurrence" : "cosine only" },
];
const gruppenKnoepfe = settingsPanel.querySelectorAll("[data-g]");
for (const r of BAU_REGLER) {
  r.el = document.getElementById(r.id);
  r.wertEl = document.getElementById(r.wert);
}
function reglerBeschriften() {
  for (const r of BAU_REGLER) r.wertEl.textContent = r.text(r.el.value);
}
function bauStandAnzeigen() {
  for (const r of BAU_REGLER) {
    r.el.disabled = !bauStand || !(bauStand.limits && bauStand.limits[r.feld]);
  }
  const merge = bauStand && bauStand.desired.merge;
  gruppenKnoepfe.forEach(b => {
    b.disabled = merge === undefined;
    b.classList.toggle("aktiv", merge !== undefined && (b.dataset.g === "an") === merge);
  });
  if (!bauStand) {   // Server ohne /api/map_settings: wenigstens zeigen, was gebaut ist
    const b = G && G.settings;
    zeigeBauStatus(b ? `Current map: ${gebautText(b)}. Changing it needs a newer server version.`
                     : "Map settings need a newer server version.", false);
    return;
  }
  const { desired, built, limits } = bauStand;
  for (const r of BAU_REGLER) {
    const grenzen = limits && limits[r.feld];
    if (grenzen) { r.el.min = grenzen[0]; r.el.max = grenzen[1]; }
    if (desired[r.feld] !== undefined) r.el.value = desired[r.feld];
  }
  reglerBeschriften();
  if (!built) {
    zeigeBauStatus("No map built yet — build it on the Mac.", true);
    return;
  }
  // Karten von vor diesen Feldern kennen `excluded`/`topics` nicht — dann zählt nur, ob
  // überhaupt etwas ausgeschlossen ist, sonst stünde grundlos "Pending". Fehlen die
  // Themen, ist die Karte noch mit den alten gerechneten Clustern gebaut: das steht aus.
  const ausschlussOffen = built.excluded === undefined
    ? sigZahl(desired.excluded) > 0
    : built.excluded !== desired.excluded;
  // Zusammengelegte Keywords (#merge): gleiches Muster wie die Ausschlussliste.
  const gruppenOffen = built.groups === undefined
    ? sigZahl(desired.groups) > 0
    : desired.groups !== undefined && built.groups !== desired.groups;
  // desired.topics fehlt nur bei einem Server, der die Themen noch nicht kennt — dann
  // wüsste er es nicht besser, und ein ewiges "Pending" wäre eine Falschmeldung.
  const themenOffen = desired.topics !== undefined && built.topics !== desired.topics;
  // Ein Wert, den der Server noch nicht kennt, kann nicht ausstehen; einer, den die
  // *Karte* noch nicht kennt, steht dagegen sehr wohl aus — sie ist von vor dem Filter.
  const reglerOffen = BAU_REGLER.some(r =>
    desired[r.feld] !== undefined && built[r.feld] !== desired[r.feld])
    || (desired.merge !== undefined && built.merge !== desired.merge);
  const offen = reglerOffen || themenOffen || ausschlussOffen || gruppenOffen;
  // Der Mac kann neu gebaut haben, während diese Karte längst geladen ist — dann zeigt
  // der Bildschirm noch die alte, obwohl der Status schon die neue meldet.
  const neuer = G.settings && built.built_at !== G.settings.built_at;
  zeigeBauStatus(
    (offen ? "Pending — applies on the next map build. Current map: "
     : neuer ? "Newer map ready — reload to see it. Built: "
     : "Current map: ") + gebautText(built), offen || neuer);
}
async function ladeBauStand() {
  if (!bauStand) zeigeBauStatus("loading …", false);
  try {
    const r = await fetch("api/map_settings");
    if (!r.ok) throw new Error(String(r.status));
    bauStand = await r.json();
  } catch { bauStand = null; }
  bauStandAnzeigen();
}
async function sendeBauStand(feld, wert) {
  try {
    const r = await fetch("api/map_settings", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ [feld]: wert }),
    });
    if (!r.ok) throw new Error(String(r.status));
    bauStand = await r.json();
    bauStandAnzeigen();
  } catch {
    zeigeBauStatus("Couldn't save the setting.", true);
  }
}
gruppenKnoepfe.forEach(b => b.onclick = () => {
  if (bauStand && b.dataset.g === (bauStand.desired.merge ? "an" : "aus")) return;
  sendeBauStand("merge", b.dataset.g === "an");
});
for (const r of BAU_REGLER) {
  r.el.addEventListener("input", reglerBeschriften);
  // erst beim Loslassen speichern, und nur das eine Feld: Ein voller Satz überschriebe
  // die anderen beiden mit dem Stand, den dieses Panel gerade zufällig anzeigt.
  r.el.addEventListener("change", () => sendeBauStand(r.feld, +r.el.value));
}
reglerBeschriften();   // Standardwerte beschriften; die echten holt das Öffnen des Panels

/* ---------- Suche ----------
   Vorschläge beim Tippen aus der Karte und aus allen Keywords (/api/map_search). Ein Keyword
   außerhalb der Karte kommt über /api/map_keyword — gerechnet wie im Kartenbau — in einen der
   freien Plätze am Ende der Knotenliste und wird ohne neues Layout eingefügt: neben einem der
   ähnlichsten Knoten, an der Stelle, deren Umgebung am besten passt. Bewertet man stattdessen
   die Umgebung des Nachbarn, landete „Jair Bolsonaro" neben „Joe Biden" (0,66) statt neben
   „Brasilien" (0,93). Die übrige Karte bleibt stehen; Eingefügtes übersteht den Wechsel der
   Projektion. */
const slotDaten = new Map();   // Platz → { vek, mom }
const einfuegBei = new Map();  // Platz → Name des Knotens, neben dem eingefügt wurde
let slotFolge = [];            // Belegungsreihenfolge; sind alle voll, wird der älteste frei
const b64Bytes = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
function nebenAufKugel(p, winkel, abstand) {
  const a = Math.abs(p[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0];
  const t1 = [p[1] * a[2] - p[2] * a[1], p[2] * a[0] - p[0] * a[2], p[0] * a[1] - p[1] * a[0]];
  const l1 = Math.hypot(...t1);
  for (let k = 0; k < 3; k++) t1[k] /= l1;
  const t2 = [p[1] * t1[2] - p[2] * t1[1], p[2] * t1[0] - p[0] * t1[2], p[0] * t1[1] - p[1] * t1[0]];
  const q = p.map((v, k) => v + abstand * (Math.cos(winkel) * t1[k] + Math.sin(winkel) * t2[k]));
  const l = Math.hypot(...q);
  return q.map(v => +(v / l).toFixed(5));
}
function slotBelegen(daten) {
  const start = G.nodes.length - SLOTS;
  let i = -1;
  for (let s = start; s < G.nodes.length; s++) if (!slotDaten.has(s)) { i = s; break; }
  if (i < 0) { i = slotFolge[0]; ausblenden(nodes[i]); }
  const dim = FIT.dim, roh = b64Bytes(daten.vek), vek = new Float32Array(dim);
  let q = 0;
  for (let k = 0; k < dim; k++) { vek[k] = (roh[k] << 24) >> 24; q += vek[k] * vek[k]; }
  q = Math.sqrt(q) || 1;
  for (let k = 0; k < dim; k++) vek[k] /= q;
  const mom = b64Bytes(daten.momentum);
  slotDaten.set(i, { vek, mom });
  slotFolge = slotFolge.filter(s => s !== i).concat(i);
  FIT.set(vek, i * dim);
  if (MOM.length >= (i + 1) * NW) MOM.set(mom.subarray(0, NW), i * NW);
  // Ähnlichkeitsfarbe des nächsten Knotens der Karte: Die Farbskala des Baus (ein 3D-UMAP)
  // lässt sich nicht fortschreiben
  let naechster = 0, best = -Infinity;
  for (let j = 0; j < start; j++) { const s = kos(i, j); if (s > best) { best = s; naechster = j; } }
  const g = Object.assign(G.nodes[i], {
    id: daten.id, n: daten.n, sw: daten.sw, src: daten.src, cluster: daten.cluster,
    spread: daten.spread, like: daten.like, nb: daten.nb, art: daten.art, streu: daten.streu,
    col: G.nodes[naechster].col, slotTeile: daten.teile && daten.teile.length ? daten.teile : undefined,
  });
  return Object.assign(nodes[i], g, { r: (2.2 + Math.sqrt(g.n) * 0.55) * KNOTEN_FAKTOR, r3: kugelRadius(g.n) });
}
function platzieren(d, sicht) {
  const kugel = projektion === "kugel" && P;
  const kand = sicht.map(x => [aehnlich(d.i, x.i), x]).sort((a, b) => b[0] - a[0]).slice(0, 8);
  let best = null;
  for (const [, c] of kand) for (let k = 0; k < 12; k++) {
    const w = k / 12 * TAU;
    let pos, abst, frei = 0;
    if (kugel) {
      pos = nebenAufKugel([P[3*c.i], P[3*c.i+1], P[3*c.i+2]], w, 0.015);
      abst = o => -(pos[0] * P[3*o.i] + pos[1] * P[3*o.i+1] + pos[2] * P[3*o.i+2]);
    } else {
      const r0 = c.r + d.r + 8;
      pos = [c.x + Math.cos(w) * r0, c.y + Math.sin(w) * r0];
      abst = o => (o.x - pos[0]) ** 2 + (o.y - pos[1]) ** 2;
      frei = Infinity;
      for (const o of sicht) frei = Math.min(frei, Math.hypot(o.x - pos[0], o.y - pos[1]) - o.r - d.r);
    }
    const umgebung = sicht.map(o => [abst(o), o]).sort((a, b) => a[0] - b[0]).slice(0, FIT_K);
    const wert = umgebung.reduce((s, [, o]) => s + aehnlich(d.i, o.i), 0) / umgebung.length;
    const ok = frei >= 0;
    if (!best || ok > best.ok || (ok === best.ok && wert > best.wert)) best = { c, w, pos, ok, wert };
  }
  if (kugel) P.set(best.pos, 3 * d.i);
  else { d.x = best.pos[0]; d.y = best.pos[1]; }
  d.vx = d.vy = 0;
  // Startlage für den nächsten Aufbau (Wechsel der Projektion): neben dem Kandidaten
  const g = G.nodes[d.i], b = G.nodes[best.c.i];
  g.ux = d.ux = +(b.ux + 8 * Math.cos(best.w)).toFixed(1);
  g.uy = d.uy = +(b.uy + 8 * Math.sin(best.w)).toFixed(1);
  g.kugelNeben = [best.c.i, best.w];
  if (kugel) g.xyz = best.pos;
  else if (b.xyz) g.xyz = nebenAufKugel(b.xyz, best.w, 0.015);
  if (!kugel && P) P.set(g.xyz, 3 * d.i);
  return best.c;
}
// Kommt die Kugel-Lage erst nach dem Einfügen, setzt sie das Eingefügte neben denselben Knoten.
function slotsAufKugel() {
  for (const i of slotDaten.keys()) {
    const g = G.nodes[i];
    if (g.kugelNeben) g.xyz = nebenAufKugel(G.nodes[g.kugelNeben[0]].xyz, g.kugelNeben[1], 0.015);
  }
}
// Kanten wie im Bau: die ähnlichsten Knoten der Karte, Gewicht nach derselben Skala. Als
// Indizes wie die des Datensatzes — die Kraft der Kanten löst sie beim Einlesen auf.
function kantenAnlegen(d, sicht) {
  const nb = sicht.map(x => [aehnlich(d.i, x.i), x]).sort((a, b) => b[0] - a[0]).slice(0, (G.settings && G.settings.edges) || 10);
  const ws = links.map(l => l.w).sort((a, b) => a - b);
  const zVon = w => {
    if (G.mix) { let lo = 0, hi = ws.length; while (lo < hi) { const m = (lo + hi) >> 1; if (ws[m] < w) lo = m + 1; else hi = m; } return ws.length ? lo / ws.length : 1; }
    const lo = ws[Math.floor(ws.length * 0.05)] ?? 0, hi = ws[ws.length - 1] ?? 1;
    return hi > lo ? Math.min(1, Math.max(0, (w - lo) / (hi - lo))) : 1;
  };
  const neu = nb.map(([w, x]) => ({ source: d.i, target: x.i, w, z: zVon(w) }));
  links.push(...neu);
  return neu;
}
function nachEinfuegen() {
  nachbarn = nodes.map(() => new Set());
  for (const l of links) { nachbarn[l.source.i].add(l.target.i); nachbarn[l.target.i].add(l.source.i); }
  kantenBuendeln();
  if (projektion === "kugel" && P) baueBoegen();
  labelFolge = nodes.slice().sort((a, b) => b.n - a.n);
  fremd = null;
  streuRangNeu(); farbenAktualisieren(); baueClusterLegende();
}
function einblenden(d) {
  d.weg = false;
  const sicht = sim.nodes();
  einfuegBei.set(d.i, platzieren(d, sicht).id);
  sim.nodes([...sicht, d]);   // ohne Anstoß: Alpha bleibt, wo es ist, die Karte steht
  kantenAnlegen(d, sicht);
  sim.force("link").links(links);
  nachEinfuegen();
}
function ausblenden(d) {
  einfuegBei.delete(d.i);
  if (slotDaten.delete(d.i)) { slotFolge = slotFolge.filter(s => s !== d.i); G.nodes[d.i].id = d.id = ""; }
  d.weg = true;
  links = links.filter(l => l.source !== d && l.target !== d);
  sim.nodes(sim.nodes().filter(x => x !== d));
  sim.force("link").links(links);
  if (auswahl === d) auswahl = null;
  if (hover === d) hover = null;
  nachEinfuegen();
}
function sucheZeile(d) {
  if (!slotDaten.has(d.i)) return "";
  const bei = einfuegBei.get(d.i);
  return `<br>From the NAS, not in the map's data set${d.slotTeile ? ` (merged with ${d.slotTeile.map(esc).join(", ")})` : ""}`
    + `${bei ? ` · placed next to „${esc(bei)}“` : ""} · <span class="suche-weg" data-i="${d.i}">remove</span>`;
}
function sucheEinrichten() {
  const feld = document.getElementById("suche");
  const liste = document.createElement("div");
  liste.id = "vorschlaege";
  document.body.appendChild(liste);
  let eintraege = [], markiert = 0, lauf = 0, timer = null, nasTreffer = [], nasStatus = "";
  const rang = (name, q) => name === q ? 0 : name.startsWith(q) ? 1
    : name.replace(/-/g, " ").split(/\s+/).some(w => w.startsWith(q)) ? 2 : name.includes(q) ? 3 : null;
  const anfrage = () => feld.value.trim().toLowerCase();
  function zusammen(q) {
    const lokal = [], bekannt = new Set();
    for (const d of nodes) {
      if (!d.id) continue;
      bekannt.add(d.id.toLowerCase());
      if (d.weg) continue;
      let r = rang(d.id.toLowerCase(), q), via = null;
      for (const t of d.teile || []) {   // ein Gruppenmitglied zählt wie der eigene Name
        const rt = rang(t.toLowerCase(), q);
        if (rt !== null && (r === null || rt < r)) { r = rt; via = t; }
      }
      if (r !== null) lokal.push({ d, name: d.id, n: d.n, rang: r, via });
    }
    const nas = nasTreffer.filter(t => !bekannt.has(t.name.toLowerCase()));
    return [...lokal, ...nas].sort((a, b) => a.rang - b.rang || b.n - a.n).slice(0, 12);
  }
  function positionieren() {
    const r = feld.getBoundingClientRect(), breite = Math.min(Math.max(r.width, 300), innerWidth - 32);
    liste.style.width = breite + "px";
    liste.style.left = Math.max(16, Math.min(r.right - breite, innerWidth - 16 - breite)) + "px";
    if (r.top > innerHeight / 2) {   // Suchfeld unten (Handy): Liste darüber
      liste.style.top = "auto"; liste.style.bottom = (innerHeight - r.top + 6) + "px";
      liste.style.maxHeight = Math.max(120, r.top - 130) + "px";
    } else {
      liste.style.bottom = "auto"; liste.style.top = (r.bottom + 6) + "px";
      liste.style.maxHeight = Math.max(120, innerHeight - r.bottom - 24) + "px";
    }
  }
  function zeichne() {
    if (!anfrage()) { liste.classList.remove("an"); return; }
    const zeilen = eintraege.map((e, j) => `<div class="v${j === markiert ? " aktiv" : ""}" data-j="${j}">`
      + `<span class="name">${esc(e.name)}${e.via ? ` <small>· ${esc(e.via)}</small>` : ""}</span>`
      + `<span class="meta${e.d ? "" : " nas"}">${dezimal(e.n)} · ${e.d ? "on map" : "from NAS"}</span></div>`);
    if (nasStatus) zeilen.push(`<div class="hinweis">${esc(nasStatus)}</div>`);
    if (!zeilen.length) zeilen.push(`<div class="hinweis">No keyword found</div>`);
    liste.innerHTML = zeilen.join("");
    positionieren();
    liste.classList.add("an");
  }
  async function nasSuche(q) {
    const meiner = ++lauf;   // Antworten kommen nicht in Reihenfolge — nur die jüngste zählt
    try {
      const r = await fetch("api/map_search?n=12&q=" + encodeURIComponent(q));
      if (!r.ok) throw new Error(String(r.status));
      const j = await r.json();
      if (meiner !== lauf || anfrage() !== q) return;
      if (j.bereit) { nasTreffer = j.treffer; nasStatus = ""; }
      else if (j.fehler) { nasTreffer = []; nasStatus = "Search beyond the map is unavailable"; }
      else { nasStatus = "Loading the keyword index …"; timer = setTimeout(() => nasSuche(q), 1500); }
    } catch {
      if (meiner !== lauf) return;
      nasTreffer = []; nasStatus = "Search beyond the map is unavailable";
    }
    eintraege = zusammen(q); zeichne();
  }
  function fertig(d) {
    liste.classList.remove("an");
    feld.value = d.id; feld.blur(); nasStatus = "";
    auswahl = d; springeZu(d); zeigePanel(); render();
  }
  async function waehle(e) {
    if (!e) return;
    if (e.d) { fertig(e.d); return; }
    if (!sim) { nasStatus = "This map can't place new keywords"; zeichne(); return; }
    nasStatus = `Loading „${e.name}“ …`; zeichne();
    try {
      await Promise.all([teil("vektoren"), teil("details")]);
      if (!FIT) throw new Error("this map has no similarity data");
      const r = await fetch("api/map_keyword?key=" + encodeURIComponent(e.key));
      const j = await r.json();
      if (!r.ok) throw new Error(j.detail || String(r.status));
      const d = slotBelegen(j);
      einblenden(d);
      fertig(d);
    } catch (err) { nasStatus = "Couldn't load: " + err.message; zeichne(); }
  }
  feld.addEventListener("input", () => {
    const q = anfrage();
    markiert = 0;
    clearTimeout(timer);
    if (!q) { nasTreffer = []; nasStatus = ""; zeichne(); return; }
    if (DEMO) { eintraege = zusammen(q); zeichne(); return; }   // nur Keywords der Karte
    // die letzten Treffer bleiben stehen, soweit sie noch passen — die Liste springt nicht
    nasTreffer = nasTreffer.filter(t => rang(t.name.toLowerCase(), q) !== null || (t.via && rang(t.via.toLowerCase(), q) !== null));
    nasStatus = "Searching …";
    eintraege = zusammen(q); zeichne();
    timer = setTimeout(() => nasSuche(q), 160);
  });
  feld.addEventListener("keydown", e => {
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      if (!eintraege.length) return;
      e.preventDefault();
      markiert = (markiert + (e.key === "ArrowDown" ? 1 : eintraege.length - 1)) % eintraege.length;
      zeichne();
    } else if (e.key === "Escape") { liste.classList.remove("an"); feld.blur(); }
    else if (e.key === "Enter") {
      e.preventDefault();
      if (!eintraege.length && anfrage()) eintraege = zusammen(anfrage());
      waehle(eintraege[markiert]);
    }
  });
  feld.addEventListener("focus", () => { if (anfrage()) { eintraege = zusammen(anfrage()); zeichne(); } });
  feld.addEventListener("blur", () => setTimeout(() => liste.classList.remove("an"), 150));
  liste.addEventListener("pointerdown", e => e.preventDefault());   // Fokus bleibt bis zum Klick im Feld
  liste.addEventListener("click", e => { const z = e.target.closest(".v"); if (z) waehle(eintraege[+z.dataset.j]); });
  panel.addEventListener("click", e => {
    const weg = e.target.closest(".suche-weg");
    if (weg) { ausblenden(nodes[+weg.dataset.i]); zeigePanel(); render(); }
  });
}
sucheEinrichten();

/* ---------- Start ---------- */

function hinweis(text) {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = T.bg;
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = T.hinweis;
  ctx.font = "14px -apple-system, sans-serif";
  ctx.textAlign = "center";
  ctx.fillText(text, W / 2, H / 2);
}

async function starte() {
  legende.innerHTML = legendeText(modus);
  if (!G || !G.nodes || !G.nodes.length) { hinweis("No map data."); return; }
  DATEN_N = G.nodes.length;
  if (projektion === "kugel") {
    hinweis("Loading …");
    try { await teil("kugel"); } catch { projektion = "flach"; }
  }
  for (let k = 0; k < SLOTS; k++) G.nodes.push({ id: "", slot: true, ux: 0, uy: 0, xyz: [0, 0, 1], n: 0,
                                                 cluster: -1, sw: {}, src: "", art: [], like: null, nb: 0 });
  buildGraph();          // setzt hatKugel und schaltet notfalls auf die Ebene zurück
  bindeEingabe();
  markiereSettings();
}

resize();
starte();
